/* Darsi — inhoud NEDERLANDS (vertaald uit het Frans, de referentietaal).
   Bronnen: 'q:S:V' = vers, 'h:naam' = hadith, 'f:naam' = referentiepunt. Niet vertalen: id's, bronnen, juiste antwoorden. */
'use strict';
CONTENU.nl={
lecons:{
/* ===================== RAMADAN & VASTEN ===================== */
'r-bienvenue':{titre:"De maand Ramadan",
 texte:["Ramadan is de 9e maand van de islamitische kalender, de Hidjri-kalender. Deze kalender is een maankalender: elke maand begint wanneer de nieuwe maansikkel zichtbaar wordt.",
  "Een maanjaar telt ongeveer 354 dagen. Ramadan schuift daardoor elk jaar zo'n tien dagen naar voren in onze kalender.",
  "In deze maand begon de openbaring van de Koran. Het vasten tijdens Ramadan werd verplicht in het 2e jaar van de Hidjra."],
 retenir:"Ramadan is de 9e maanmaand, de maand van de Koran en van het vasten.",
 sources:['q:2:185','h:croissant'],
 quiz:[
  {q:"Welke maand is Ramadan in de islamitische kalender (Hidjri-kalender)?",c:["De 9e maand","De 1e maand","De 12e maand","De 7e maand"],b:0,e:"Ramadan is de 9e maand. De 1e maand van het Hidjri-jaar is Muharram.",s:['f:mois']},
  {q:"Op welk hemellichaam is de islamitische kalender (Hidjri-kalender) gebaseerd?",c:["De maan","De zon","De sterren","Op geen enkel hemellichaam"],b:0,e:"Elke maand begint wanneer de nieuwe maansikkel zichtbaar wordt.",s:['q:2:189','h:croissant']},
  {q:"Waarom schuift de datum van Ramadan elk jaar ongeveer 11 dagen naar voren?",c:["Omdat het maanjaar korter is dan het zonnejaar","Omdat de geleerden de datum elk jaar verschuiven","Omdat het Hidjri-jaar 13 maanden telt","Omdat men de Perzische zonnekalender volgt"],b:0,e:"Een maanjaar telt ongeveer 354 dagen, dus zo'n 11 dagen minder dan een zonnejaar.",s:['q:9:36']},
  {q:"Welke belangrijke gebeurtenis begon tijdens de maand Ramadan?",c:["De openbaring van de Koran","De bouw van de Kaaba","De Hidjra naar Medina","De slag bij Uhud"],b:0,e:"De openbaring van de Koran begon tijdens Ramadan.",s:['q:2:185']},
  {q:"Hoeveel maanden telt het islamitische jaar (Hidjri-jaar)?",c:["12","10","13","11"],b:0,e:"Het Hidjri-jaar telt 12 maanmaanden.",s:['q:9:36']},
  {q:"Bij welk teken begint men volgens de hadith met het vasten van Ramadan?",c:["Wanneer men de nieuwe maansikkel ziet","Wanneer men de volle maan ziet","Elk jaar op 15 Sjaʿban","Na de eerste vrijdag na Sjaʿban"],b:0,e:"“Vast wanneer jullie hem zien”: het gaat om de maansikkel.",s:['h:croissant']},
  {q:"Hoe heet de maand na Ramadan, waarvan de 1e dag het Suikerfeest (Eid al-Fitr) is?",c:["Sjawwal","Sjaʿban","Radjab","Muharram"],b:0,e:"Op 1 Sjawwal valt het Suikerfeest (Eid al-Fitr).",s:['f:mois']},
  {q:"Welke maand van de islamitische kalender gaat direct aan Ramadan vooraf?",c:["Sjaʿban","Sjawwal","Dhul-Hiddja","Safar"],b:0,e:"Sjaʿban is de 8e maand, vlak voor Ramadan.",s:['f:mois']},
  {q:"In welk jaar van de Hidjra werd het vasten van Ramadan verplicht?",c:["Het jaar 2","Het jaar 1","Het jaar 10","Het jaar 8"],b:0,e:"Het vasten van Ramadan werd in Medina voorgeschreven, in het jaar 2 van de Hidjra.",s:['f:jeune2']},
  {q:"Hoeveel dagen kan de maand Ramadan duren?",c:["29 of 30 dagen","Altijd 30 dagen","28 dagen","31 dagen"],b:0,e:"Een maanmaand duurt 29 of 30 dagen, afhankelijk van wanneer de volgende maansikkel verschijnt.",s:['h:croissant']}
 ]},
'r-jeuner':{titre:"Wie moet vasten?",
 texte:["Het vasten van Ramadan is verplicht voor de moslim die volwassen (geslachtsrijp) is, bij zijn verstand is en in staat is om te vasten.",
  "De zieke en de reiziger mogen het vasten nalaten en de dagen later inhalen. Een vrouw die menstrueert, vast niet en haalt de dagen daarna in.",
  "Wie nooit zal kunnen vasten, zoals een zeer oude persoon, geeft voor elke gemiste dag een arme te eten: dat is de fidya."],
 retenir:"Er bestaan verlichtingen: Allah wil voor ons het gemak.",
 sources:['q:2:184','q:2:185'],
 quiz:[
  {q:"Wat moet de reiziger doen die tijdens Ramadan sommige dagen niet heeft gevast?",c:["Die dagen later inhalen","Helemaal niets","Een boete betalen","Dubbel zoveel vasten"],b:0,e:"Hij haalt na Ramadan hetzelfde aantal dagen in.",s:['q:2:184']},
  {q:"Hoe heet de compensatie waarbij men voor elke gemiste vastendag een arme te eten geeft?",c:["De fidya","De sadaqa","De zakat al-fitr","De kaffara"],b:0,e:"De fidya geldt vooral voor wie de dagen nooit zal kunnen inhalen, zoals zeer oude mensen.",s:['q:2:184']},
  {q:"Is het vasten van Ramadan verplicht voor een kind dat nog niet geslachtsrijp is?",c:["Nee, maar men kan het eraan laten wennen","Ja, vanaf 7 jaar","Ja, maar alleen op vrijdag","Alleen tijdens de laatste tien dagen"],b:0,e:"Het is niet verplicht. Toch lieten de metgezellen hun kinderen aan het vasten wennen, bijvoorbeeld op de dag van ʿAsjoera.",s:['h:enfants']},
  {q:"Wat doet een vrouw die tijdens Ramadan menstrueert?",c:["Ze vast niet en haalt de dagen daarna in","Ze vast toch","Ze haalt de dagen nooit in","Ze vast de halve dag"],b:0,e:"Ze vast niet en haalt de gemiste dagen na Ramadan in.",s:['h:regles']},
  {q:"Moet een zieke die tijdens Ramadan niet vast de gemiste dagen inhalen?",c:["Ja, wanneer hij daartoe in staat is","Nee, nooit","Ja, maar dubbel","Nee, hij betaalt altijd een boete"],b:0,e:"Hij haalt een gelijk aantal dagen in wanneer hij daartoe in staat is.",s:['q:2:184']},
  {q:"Moet een vrouw de gebeden inhalen die ze tijdens haar menstruatie niet heeft verricht?",c:["Nee, ze haalt alleen het vasten in","Ja, alle gebeden","Ja, de helft van de gebeden","Alleen het vrijdaggebed"],b:0,e:"Ze haalt het vasten in, maar niet het gebed.",s:['h:regles']},
  {q:"Wat wil Allah volgens het vers over het vasten voor de gelovigen?",c:["Het gemak","De moeilijkheid","De vermoeidheid","De rijkdom"],b:0,e:"“Allah wil voor jullie het gemak, Hij wil voor jullie niet de moeilijkheid.”",s:['q:2:185']},
  {q:"Wat doet een zeer oude persoon die nooit meer zal kunnen vasten?",c:["Hij geeft voor elke dag een arme te eten","Hij vast toch","Hij hoeft niets te doen","Hij haalt de dagen na de volgende Ramadan in"],b:0,e:"Dat is de fidya: een maaltijd voor een arme per niet-gevaste dag.",s:['q:2:184']},
  {q:"Voor wie is het vasten van Ramadan verplicht?",c:["Voor de moslim die volwassen, bij zijn verstand en in staat tot vasten is","Voor alle kinderen","Alleen voor mannen","Alleen voor wie de hadj heeft verricht"],b:0,e:"Dit zijn de voorwaarden die de geleerden noemen.",s:['f:conditions']},
  {q:"Werd het vasten volgens de Koran ook al vóór de moslims voorgeschreven?",c:["Ja, aan hen die hen voorgingen","Nee, nooit","Alleen aan de mensen van Mekka","Alleen aan het volk van Noeh"],b:0,e:"“Het vasten is jullie voorgeschreven, zoals het werd voorgeschreven aan hen die vóór jullie waren.”",s:['q:2:183']}
 ]},
'r-rompt':{titre:"Wat het vasten verbreekt",
 texte:["Het vasten begint bij de dageraad, op het tijdstip van het Fadjr-gebed, en eindigt bij zonsondergang, op het tijdstip van het Maghrib-gebed.",
  "Overdag bewust eten, drinken of intieme omgang hebben verbreekt het vasten.",
  "Wie uit vergetelheid eet of drinkt, zet zijn vasten voort: het blijft geldig."],
 retenir:"Uit vergetelheid eten of drinken maakt het vasten niet ongeldig.",
 sources:['q:2:187','h:oubli'],
 quiz:[
  {q:"Op welk moment van de dag begint het vasten van Ramadan?",c:["Bij de dageraad (Fadjr)","Om middernacht","Bij zonsopgang","Om twaalf uur 's middags"],b:0,e:"Het vasten begint bij de dageraad, wanneer de witte draad zich onderscheidt van de zwarte draad.",s:['q:2:187']},
  {q:"Op welk moment verbreekt men het vasten van Ramadan?",c:["Bij zonsondergang (Maghrib)","Als het volledig donker is (ʿIshaa')","Om 16 uur","Midden in de nacht"],b:0,e:"Men verbreekt het vasten zodra de zon onder is.",s:['h:coucher']},
  {q:"Een vastende drinkt water omdat hij vergeten is dat hij vastte. Wat gebeurt er met zijn vasten?",c:["Het blijft geldig","Het is ongeldig","Hij moet het dubbel doen","Dat hangt af van de hoeveelheid"],b:0,e:"Hij maakt zijn vasten af: het is Allah Die hem te eten en te drinken heeft gegeven.",s:['h:oubli']},
  {q:"Wat gebeurt er als een vastende midden op een Ramadan-dag bewust eet?",c:["Zijn vasten is verbroken","Er verandert niets","Het mag als hij in de moskee is","Het mag na het Dhohr-gebed"],b:0,e:"Overdag bewust eten verbreekt het vasten.",s:['q:2:187']},
  {q:"Tot wanneer mag men volgens de Koran eten en drinken in de nachten van Ramadan?",c:["Tot de witte draad van de dageraad zich onderscheidt van de zwarte draad van de nacht","Tot middernacht","Tot zonsopgang","Tot het ʿIshaa'-gebed"],b:0,e:"Dat is het beeld uit vers 187 van soera Al-Baqara.",s:['q:2:187']},
  {q:"Wat stelt “de witte draad” voor in het vers over het vasten?",c:["Het licht van de dageraad","Een echte draad van wol","De maansikkel","De eerste avondster"],b:0,e:"De witte draad is het licht van de dageraad, de zwarte draad de duisternis van de nacht.",s:['q:2:187']},
  {q:"Mag men tijdens Ramadan 's nachts, na zonsondergang, eten en drinken?",c:["Ja, tot de dageraad","Nee, de hele maand nooit","Alleen water","Alleen na het tarawih-gebed"],b:0,e:"Het vasten geldt alleen overdag, van de dageraad tot zonsondergang.",s:['q:2:187']},
  {q:"Wie heeft volgens de hadith degene “te eten en te drinken gegeven” die tijdens het vasten uit vergetelheid eet of drinkt?",c:["Allah","Zijn familie","Een engel","Niemand"],b:0,e:"Zijn vasten blijft geldig: het is Allah Die hem te eten en te drinken heeft gegeven.",s:['h:oubli']},
  {q:"Is intieme omgang tussen echtgenoten overdag tijdens Ramadan toegestaan?",c:["Nee, het verbreekt het vasten","Ja, op elk moment","Ja, 's middags","Alleen op de dag van ʿAsjoera"],b:0,e:"Vers 187 staat het toe in de nachten van Ramadan; overdag verbreekt het het vasten.",s:['q:2:187']},
  {q:"Welk gebed markeert het einde van de vastendag?",c:["Het Maghrib-gebed","Het Fadjr-gebed","Het Dhohr-gebed","Het ʿIshaa'-gebed"],b:0,e:"Maghrib is het gebed bij zonsondergang, het moment waarop het vasten wordt verbroken.",s:['h:coucher']}
 ]},
'r-suhur':{titre:"De suhoer en de iftar",
 texte:["De suhoer is de maaltijd die vóór de dageraad wordt gegeten. De Profeet ﷺ moedigde aan om die te nemen, want er zit zegen in.",
  "De iftar is het verbreken van het vasten bij zonsondergang. Het wordt aanbevolen om die niet uit te stellen.",
  "De soenna is om het vasten te verbreken met verse dadels, anders met gedroogde dadels, anders met een paar slokjes water."],
 retenir:"Suhoer vóór de dageraad. Iftar meteen bij zonsondergang, met dadels.",
 sources:['h:suhur','h:dattes'],
 quiz:[
  {q:"Hoe heet de maaltijd die tijdens Ramadan vóór de dageraad wordt gegeten?",c:["De suhoer","De iftar","De walima","De ʿaqiqa"],b:0,e:"De suhoer is de maaltijd aan het einde van de nacht, vóór Fadjr.",s:['h:suhur']},
  {q:"Wat zit er volgens de hadith in de suhoer-maaltijd?",c:["Een zegen","Een verplichting","Niets bijzonders","Een beproeving"],b:0,e:"“Neem de suhoer, want in de suhoer zit zegen.”",s:['h:suhur']},
  {q:"Waarmee verbrak de Profeet ﷺ bij voorkeur zijn vasten?",c:["Met dadels","Met kamelenmelk","Met harira","Met brood"],b:0,e:"Met verse dadels, anders met gedroogde dadels, anders met een paar slokjes water.",s:['h:dattes']},
  {q:"Moet men de iftar (het verbreken van het vasten) na zonsondergang uitstellen?",c:["Nee, het wordt aanbevolen om ermee te haasten","Ja, een uur","Ja, tot ʿIshaa'","Dat maakt niets uit"],b:0,e:"Het wordt aanbevolen om het vasten meteen bij zonsondergang te verbreken.",s:['h:hater']},
  {q:"Hoe heet de maaltijd waarmee het vasten bij zonsondergang wordt verbroken?",c:["De iftar","De suhoer","De ghoesl","De dhikr"],b:0,e:"De iftar is het verbreken van het vasten.",s:['h:hater']},
  {q:"Waarmee verbrak de Profeet ﷺ zijn vasten als er geen dadels waren?",c:["Met een paar slokjes water","Met honing","Met geitenmelk","Met vijgen"],b:0,e:"Met verse dadels, anders gedroogde, anders een paar slokjes water.",s:['h:dattes']},
  {q:"Verbrak de Profeet ﷺ zijn vasten vóór of na het Maghrib-gebed?",c:["Vóór het gebed","Na het gebed","De volgende dag","Na het ʿIshaa'-gebed"],b:0,e:"Hij verbrak zijn vasten vóór het gebed, met een paar dadels.",s:['h:dattes']},
  {q:"Volgens de hadith: zolang de mensen zich haasten om het vasten te verbreken, blijven ze…",c:["In het goede","In twijfel","In gevaar","Zonder beloning"],b:0,e:"“De mensen blijven in het goede zolang ze zich haasten om het vasten te verbreken.”",s:['h:hater']},
  {q:"Is de suhoer verplicht om het vasten geldig te laten zijn?",c:["Nee, maar hij wordt sterk aanbevolen","Ja, anders is het vasten ongeldig","Ja, alleen op de eerste dag","Hij is verboden"],b:0,e:"Het is een soenna: de Profeet ﷺ moedigde hem aan vanwege de zegen.",s:['h:suhur']},
  {q:"Welk soort dadels had de voorkeur van de Profeet ﷺ om het vasten te verbreken?",c:["Verse dadels (rutab)","Gedroogde dadels (tamr)","Gedroogde vijgen","Rozijnen"],b:0,e:"Hij begon met verse dadels; als die er niet waren, met gedroogde dadels.",s:['h:dattes']}
 ]},
'r-merites':{titre:"De verdiensten van het vasten",
 texte:["Allah heeft het vasten voorgeschreven opdat de gelovige godsvrucht (taqwa) bereikt: het besef van Allah bij elke daad.",
  "De Profeet ﷺ beloofde vergeving van de vorige zonden aan wie Ramadan vast uit geloof en in de hoop op Allahs beloning.",
  "Aan het einde van de maand geeft elke moslim de zakat al-fitr vóór het gebed van het Suikerfeest. Die zuivert de vastende en geeft de armen te eten."],
 retenir:"Het vasten leidt tot godsvrucht. De zakat al-fitr wordt gegeven vóór het feestgebed.",
 sources:['q:2:183','h:pardon','h:fitr'],
 quiz:[
  {q:"Met welk doel heeft Allah volgens de Koran het vasten voorgeschreven?",c:["Om godsvrucht (taqwa) te bereiken","Alleen om het lichaam te zuiveren","Om de Hidjra te herdenken","Om de zakat te vervangen"],b:0,e:"Het vers dat het vasten voorschrijft, eindigt met de hoop godsvrucht te bereiken.",s:['q:2:183']},
  {q:"Wat krijgt volgens de hadith degene die Ramadan vast uit geloof en in de hoop op Allahs beloning?",c:["Zijn vorige zonden worden vergeven","Hij hoeft niet meer te bidden","Hij is vrijgesteld van zakat","Niets bijzonders"],b:0,e:"Zijn vorige zonden worden hem vergeven.",s:['h:pardon']},
  {q:"Wanneer moet de zakat al-fitr worden gegeven?",c:["Vóór het gebed van het Suikerfeest (Eid al-Fitr)","Een maand na Ramadan","Alleen aan het begin van Ramadan","Op elk moment van het jaar"],b:0,e:"De Profeet ﷺ beval haar te geven voordat de mensen naar buiten gingen voor het feestgebed.",s:['h:fitr']},
  {q:"Wat betekent het woord “taqwa”?",c:["Godsvrucht, het besef van Allah","Geduld (sabr)","Dankbaarheid (sjoekr)","Berouw (tawba)"],b:0,e:"Taqwa is het ontzag voor Allah dat aanzet tot het goede.",s:['q:2:183']},
  {q:"Wie moet de zakat al-fitr geven?",c:["Elke moslim, jong of oud, man of vrouw","Alleen de rijken","Alleen de mannen","Alleen wie de hele maand heeft gevast"],b:0,e:"De hadith schrijft haar voor aan elke moslim; het gezinshoofd geeft haar voor zijn gezinsleden.",s:['h:fitr']},
  {q:"Welke hoeveelheid voedsel legt de hadith vast voor de zakat al-fitr?",c:["Eén saʿ","Eén mithqal goud","Eén mudd tarwe","Eén zilveren dirham"],b:0,e:"Een saʿ is een maat van ongeveer vier keer de holte van twee handen samen.",s:['h:fitr']},
  {q:"Welke voedingsmiddelen worden genoemd in de hadith over de zakat al-fitr, overgeleverd door Ibn ʿUmar?",c:["Dadels of gerst","Rijst of couscous","Vlees of vis","Melk of honing"],b:0,e:"Een saʿ dadels of een saʿ gerst.",s:['h:fitr']},
  {q:"Onder welke voorwaarden wist het vasten van Ramadan volgens de hadith de vorige zonden uit?",c:["Met geloof en de hoop op Allahs beloning","Door in stilte te vasten","Door 40 dagen te vasten","Zonder enige voorwaarde"],b:0,e:"Men moet vasten uit geloof en in de hoop op Allahs beloning.",s:['h:pardon']},
  {q:"Wat is volgens de hadith van Ibn ʿAbbas het doel van de zakat al-fitr?",c:["De vastende zuiveren en de armen te eten geven","De bouw van moskeeën bekostigen","Het vasten van zieken vervangen","De imam van de tarawih belonen"],b:0,e:"Ze zuivert de vastende van zijn ijdele woorden en geeft de armen te eten.",s:['h:fitr_but']},
  {q:"Met welke aanspreking begint het vers dat het vasten van Ramadan voorschrijft?",c:["“O jullie die geloven!”","“O mensen!”","“O Profeet!”","“O kinderen van Adam!”"],b:0,e:"Vers 183 van soera Al-Baqara begint met “O jullie die geloven!”.",s:['q:2:183']}
 ]},
'r-nuits':{titre:"De nachten van Ramadan",
 texte:["De nachten van Ramadan zijn een gelegenheid om meer te bidden. Het nachtgebed van Ramadan heet tarawih. De Profeet ﷺ beloofde vergeving aan wie de nachten van Ramadan in gebed doorbrengt uit geloof en in de hoop op de beloning.",
  "In de laatste tien nachten deed hij nog meer zijn best: hij bleef 's nachts op in gebed en maakte zijn familie wakker.",
  "Hij deed ook iʿtikaf: een spirituele afzondering in de moskee tijdens de laatste tien dagen, en dat tot het einde van zijn leven."],
 retenir:"Tarawih, de laatste tien nachten, iʿtikaf: de nachten van Ramadan breng je door in gebed.",
 sources:['h:qiyam','h:dixnuits','h:itikaf'],
 quiz:[
  {q:"Hoe heet het nachtgebed dat tijdens Ramadan wordt verricht?",c:["Tarawih","Het Doeha-gebed","Het istikhara-gebed","Het dodengebed"],b:0,e:"Tarawih is het gebed van de nachten van Ramadan.",s:['h:qiyam']},
  {q:"Wat krijgt volgens de hadith degene die de nachten van Ramadan in gebed doorbrengt uit geloof en in de hoop op de beloning?",c:["Zijn vorige zonden worden vergeven","Een plaats op de eerste rij in de moskee","Hij hoeft niet meer te vasten","Niets bijzonders"],b:0,e:"Zijn vorige zonden worden hem vergeven.",s:['h:qiyam']},
  {q:"Wat is iʿtikaf?",c:["Een spirituele afzondering in de moskee","Een reis naar Mekka","Het vasten van ʿAsjoera","Een aalmoes"],b:0,e:"Men blijft in de moskee om zich aan de aanbidding te wijden.",s:['h:itikaf']},
  {q:"In welke periode van Ramadan deed de Profeet ﷺ iʿtikaf?",c:["De laatste tien dagen","De eerste tien dagen","Alleen de eerste dag","Na het Suikerfeest"],b:0,e:"Hij deed het tijdens de laatste tien dagen van Ramadan.",s:['h:itikaf']},
  {q:"Wat deed de Profeet ﷺ tijdens de laatste tien nachten van Ramadan?",c:["Hij bleef op in gebed en maakte zijn familie wakker","Hij ging op reis","Hij ging vroeger slapen","Hij stopte met vasten"],b:0,e:"Hij deed nog meer zijn best in de aanbidding.",s:['h:dixnuits']},
  {q:"Heeft de Profeet ﷺ iʿtikaf gedaan tot het einde van zijn leven?",c:["Ja, tot zijn dood","Nee, maar één keer","Nee, nooit","Alleen in Mekka"],b:0,e:"ʿAisja vertelt dat hij het deed totdat Allah hem tot Zich nam.",s:['h:itikaf']},
  {q:"Waar wordt iʿtikaf gedaan?",c:["In de moskee","Thuis","In de grot Hira","Op de begraafplaats"],b:0,e:"De Koran noemt hen die zich in de moskeeën afzonderen.",s:['q:2:187']},
  {q:"Welke zeer belangrijke nacht valt in de laatste tien nachten van Ramadan?",c:["Laylat al-Qadr, de Nacht van de Beschikking","De nacht van de Hidjra","De nacht van het Offerfeest","De nacht van de Mawlid"],b:0,e:"Je moet haar zoeken in de oneven nachten van de laatste tien nachten.",s:['h:qadr']},
  {q:"Is het tarawih-gebed verplicht?",c:["Nee, het is een vrijwillig gebed dat sterk wordt aanbevolen","Ja, net als de vijf gebeden","Ja, maar alleen in de moskee","Het is verboden"],b:0,e:"De Profeet ﷺ verrichtte het enkele nachten in groep en stopte toen, uit vrees dat het verplicht zou worden.",s:['h:tarawih']},
  {q:"Waarom stopte de Profeet ﷺ na enkele nachten met het leiden van de tarawih in groep?",c:["Uit vrees dat het verplicht zou worden","Omdat hij ziek was","Omdat de moskee te klein was","Omdat Ramadan voorbij was"],b:0,e:"Hij vreesde dat het verplicht zou worden gemaakt voor zijn gemeenschap.",s:['h:tarawih']}
 ]},
'r-qadr':{titre:"Laylat al-Qadr, de Nacht van de Beschikking",
 texte:["Laylat al-Qadr, de Nacht van de Beschikking, is de nacht waarin de openbaring van de Koran begon.",
  "Allah zegt dat ze “beter is dan duizend maanden”. De engelen dalen erin neer, en ze is vrede tot de dageraad. Er is een hele soera aan gewijd: soera Al-Qadr (97).",
  "Men zoekt haar in de laatste tien nachten van Ramadan, vooral de oneven nachten, door veel te bidden en smeekbeden te doen."],
 retenir:"Beter dan duizend maanden. Te zoeken in de oneven nachten van de laatste tien nachten.",
 sources:['q:97:1','q:97:3','h:qadr'],
 quiz:[
  {q:"Volgens de Koran is de Nacht van de Beschikking (Laylat al-Qadr) beter dan hoeveel tijd?",c:["Duizend maanden","Honderd dagen","Een jaar","Tien nachten"],b:0,e:"Ze is beter dan duizend maanden, dus meer dan 83 jaar.",s:['q:97:3']},
  {q:"Welke soera van de Koran is gewijd aan de Nacht van de Beschikking (Laylat al-Qadr)?",c:["Al-Qadr","Al-Fatiha","Al-Ikhlas","Ya-Sin"],b:0,e:"Soera 97, Al-Qadr, draagt de naam van deze nacht.",s:['q:97:1']},
  {q:"In welke nachten van Ramadan moet men vooral naar de Nacht van de Beschikking (Laylat al-Qadr) zoeken?",c:["De oneven nachten van de laatste tien nachten","De eerste tien nachten","De eerste nacht","De nacht van het Suikerfeest"],b:0,e:"De oneven nachten van de laatste tien: 21, 23, 25, 27 en 29.",s:['h:qadr']},
  {q:"Welke gebeurtenis vond plaats in de Nacht van de Beschikking (Laylat al-Qadr)?",c:["Het begin van de openbaring van de Koran","De Hidjra naar Medina","De geboorte van de Profeet ﷺ","De eerste bedevaart"],b:0,e:"De openbaring van de Koran begon in deze nacht.",s:['q:97:1']},
  {q:"Wie dalen volgens soera Al-Qadr neer in de Nacht van de Beschikking?",c:["De engelen en de Geest (Djibriel)","De profeten","De djinn","Niemand"],b:0,e:"De engelen en de Geest dalen erin neer, met toestemming van hun Heer.",s:['q:97:4']},
  {q:"Tot wanneer is de Nacht van de Beschikking volgens soera Al-Qadr vrede?",c:["Tot het aanbreken van de dageraad","Tot middernacht","Tot het einde van Ramadan","Tot het Suikerfeest"],b:0,e:"“Vrede is zij, tot het aanbreken van de dageraad.”",s:['q:97:5']},
  {q:"Hoeveel verzen telt soera Al-Qadr?",c:["5","7","3","10"],b:0,e:"Soera Al-Qadr telt 5 verzen.",s:['q:97:5']},
  {q:"Duizend maanden zijn ongeveer hoeveel jaar?",c:["Meer dan 83 jaar","10 jaar","40 jaar","1000 jaar"],b:0,e:"1000 maanden ÷ 12 ≈ 83 jaar en 4 maanden: meer dan een heel leven.",s:['q:97:3']},
  {q:"Wat zijn de oneven nachten van de laatste tien nachten van Ramadan?",c:["21, 23, 25, 27 en 29","20, 22, 24, 26 en 28","1, 3, 5, 7 en 9","11, 13, 15, 17 en 19"],b:0,e:"Dit zijn de aanbevolen nachten om Laylat al-Qadr te zoeken.",s:['h:qadr']},
  {q:"Welke smeekbede leerde de Profeet ﷺ aan ʿAisja voor de Nacht van de Beschikking?",c:["“Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî”","“Bismi Llâh”","“Allâhu akbar”","“Subḥâna Llâh”"],b:0,e:"“O Allah, U bent Degene Die vergeeft, U houdt van vergeving, vergeef mij dus.”",s:['h:afw']}
 ]},
'r-aid':{titre:"Het Suikerfeest (Eid al-Fitr)",
 texte:["Het Suikerfeest (Eid al-Fitr) is het feest van het verbreken van het vasten. Het valt op de 1e dag van de maand Sjawwal, direct na Ramadan.",
  "Voordat hij naar buiten ging voor het feestgebed, at de Profeet ﷺ een paar dadels, in een oneven aantal. De zakat al-fitr moet vóór dit gebed worden gegeven.",
  "Na het Suikerfeest wordt aanbevolen om zes dagen van de maand Sjawwal te vasten: samen met Ramadan is dat alsof je het hele jaar hebt gevast."],
 retenir:"1 Sjawwal: het Suikerfeest. Dadels vóór het gebed, daarna zes dagen van Sjawwal.",
 sources:['h:aid_dattes','h:shawwal','q:2:185'],
 quiz:[
  {q:"Op welke dag valt het Suikerfeest (Eid al-Fitr)?",c:["Op de 1e dag van Sjawwal","Op 27 Ramadan","Op 10 Dhul-Hiddja","Op 1 Muharram"],b:0,e:"Het Suikerfeest volgt direct op de maand Ramadan.",s:['f:mois']},
  {q:"Wat betekent “Eid al-Fitr”?",c:["Het feest van het verbreken van het vasten","Het Offerfeest","Het feest van de Hidjra","Het feest van de geboorte van de Profeet ﷺ"],b:0,e:"Fitr betekent het verbreken van het vasten.",s:['f:aid']},
  {q:"Wat at de Profeet ﷺ voordat hij naar buiten ging voor het gebed van het Suikerfeest?",c:["Een paar dadels","Vijgen","Vlees","Niets, hij vastte"],b:0,e:"Op de dag van het Suikerfeest ging hij niet naar buiten zonder een paar dadels te hebben gegeten.",s:['h:aid_dattes']},
  {q:"In welk aantal at de Profeet ﷺ de dadels op de ochtend van het Suikerfeest?",c:["In een oneven aantal","Altijd twee","Altijd zeven","In een even aantal"],b:0,e:"Anas vertelt dat hij ze in een oneven aantal at.",s:['h:aid_dattes']},
  {q:"Hoeveel feesten (Eid) kent de islam per jaar?",c:["2","1","3","5"],b:0,e:"Het Suikerfeest (Eid al-Fitr) en het Offerfeest (Eid al-Adha).",s:['f:aid']},
  {q:"Hoeveel dagen van Sjawwal wordt volgens de hadith aanbevolen te vasten na Ramadan?",c:["6","3","10","30"],b:0,e:"Zes dagen van Sjawwal, aaneengesloten of niet.",s:['h:shawwal']},
  {q:"Waar staat volgens de hadith het vasten van Ramadan plus zes dagen van Sjawwal gelijk aan?",c:["Het hele jaar vasten","De hadj verrichten","Een maand extra vasten","Niets bijzonders"],b:0,e:"Het is alsof hij het hele jaar heeft gevast.",s:['h:shawwal']},
  {q:"Vóór welk gebed moet de zakat al-fitr gegeven zijn?",c:["Het feestgebed","Het vrijdaggebed","Het Maghrib-gebed","De tarawih"],b:0,e:"Ze moet worden gegeven voordat de mensen naar buiten gaan voor het feestgebed.",s:['h:fitr']},
  {q:"Wat doen de gelovigen volgens vers 185 van soera Al-Baqara wanneer het aantal dagen van Ramadan is voltooid?",c:["Ze verkondigen de grootheid van Allah","Ze beginnen opnieuw te vasten","Ze doen iʿtikaf","Ze gaan Medina bezoeken"],b:0,e:"Het vers nodigt uit om de grootheid van Allah te verkondigen voor de ontvangen leiding: dat is de takbier van het feest.",s:['q:2:185']},
  {q:"Wat is het andere grote feest van de islam, dat tijdens de bedevaart wordt gevierd?",c:["Het Offerfeest (Eid al-Adha)","Het Suikerfeest (Eid al-Fitr)","De Mawlid","1 Muharram"],b:0,e:"Het Offerfeest (Eid al-Adha) valt op 10 Dhul-Hiddja.",s:['f:aid']}
 ]},

/* ===================== ZUILEN & GEBED ===================== */
'p-piliers':{titre:"De vijf zuilen van de islam",
 texte:["De islam rust op vijf zuilen, genoemd in een authentieke hadith overgeleverd door al-Boechari en Muslim.",
  "De sjahada, de geloofsgetuigenis. De salat, de vijf dagelijkse gebeden. De zakat, de verplichte aalmoes. De hadj, de bedevaart naar Mekka voor wie daartoe de middelen heeft. De sawm, het vasten van Ramadan.",
  "Deze vijf zuilen zijn het fundament van de geloofspraktijk van de moslim, het hele jaar door."],
 retenir:"Sjahada, salat, zakat, hadj, het vasten van Ramadan.",
 sources:['h:piliers'],
 quiz:[
  {q:"Hoeveel zuilen telt de islam?",c:["5","3","4","6"],b:0,e:"De islam rust op vijf zuilen.",s:['h:piliers']},
  {q:"Hoe heet vasten in het Arabisch?",c:["Sawm (of siyam)","Salat","Zakat","Hadj"],b:0,e:"Vasten heet sawm of siyam; dat is het woord uit het vers dat het voorschrijft.",s:['q:2:183']},
  {q:"Voor wie is de bedevaart naar Mekka (hadj) verplicht?",c:["Voor wie de middelen heeft, één keer in het leven","Voor iedereen, elk jaar","Alleen voor mannen","Alleen tijdens Ramadan"],b:0,e:"De hadj is één keer in het leven verplicht, voor wie er lichamelijk en financieel toe in staat is.",s:['q:3:97']},
  {q:"Hoeveel verplichte gebeden verricht een moslim per dag?",c:["5","3","7","2"],b:0,e:"Fadjr, Dhohr, ʿAsr, Maghrib en ʿIshaa'.",s:['h:cinq']},
  {q:"Wat is de eerste zuil van de islam?",c:["De sjahada, de geloofsgetuigenis","Het vasten","De hadj","De zakat"],b:0,e:"De sjahada wordt in de hadith als eerste genoemd.",s:['h:piliers']},
  {q:"Welke zuil van de islam is de verplichte aalmoes?",c:["De zakat","De salat","De sawm","De sjahada"],b:0,e:"De zakat wordt elk jaar gegeven over bezittingen die een drempel bereiken.",s:['h:piliers']},
  {q:"Welke zuil van de islam wordt in de maand Ramadan beoefend?",c:["Het vasten (sawm)","De hadj","De zakat","De sjahada"],b:0,e:"Het vasten van Ramadan is een van de vijf zuilen.",s:['h:piliers']},
  {q:"Welke zuil van de islam bestaat uit een reis naar Mekka?",c:["De hadj","De salat","De sawm","De zakat"],b:0,e:"De hadj is de bedevaart naar het Heilige Huis.",s:['q:3:97']},
  {q:"Hoe vaak in het leven is de hadj volgens de hadith verplicht?",c:["Eén keer","Elk jaar","Drie keer","Zeven keer"],b:0,e:"De Profeet ﷺ verduidelijkte dat hij niet elk jaar verplicht is.",s:['h:hajj_une']},
  {q:"Welke metgezel heeft de hadith over de vijf zuilen van de islam overgeleverd?",c:["ʿAbdallah ibn ʿUmar","Abu Bakr","Bilal","Khalid ibn al-Walid"],b:0,e:"De hadith is overgeleverd door Ibn ʿUmar.",s:['h:piliers']}
 ]},
'p-shahada':{titre:"De sjahada, de geloofsgetuigenis",
 texte:["De sjahada is de geloofsgetuigenis: “Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh”.",
  "Ze betekent: “Ik getuig dat er geen god is dan Allah, en ik getuig dat Mohammed de Boodschapper van Allah is.”",
  "Het is de eerste zuil: daarmee treedt men toe tot de islam. Ze bevestigt de eenheid van Allah, de tawhied, samengevat in soera Al-Ikhlas."],
 retenir:"Lâ ilâha illâ Llâh, Muḥammadun rasûlu Llâh.",
 sources:['q:47:19','q:48:29','h:piliers'],
 quiz:[
  {q:"Welke zuil van de islam is de geloofsgetuigenis?",c:["De sjahada","De salat","De zakat","De hadj"],b:0,e:"De sjahada is de eerste zuil.",s:['h:piliers']},
  {q:"Wat betekent “lâ ilâha illâ Llâh”?",c:["Er is geen god dan Allah","Allah is de Grootste","Glorie aan Allah","In de naam van Allah"],b:0,e:"Dat is het eerste deel van de sjahada.",s:['q:47:19']},
  {q:"Wat betekent “Muḥammadun rasûlu Llâh”?",c:["Mohammed is de Boodschapper van Allah","Mohammed is een engel","Mohammed is de eerste mens","Mohammed is een koning"],b:0,e:"Dat is het tweede deel van de sjahada.",s:['q:48:29']},
  {q:"Hoe heet het geloof in de eenheid van Allah?",c:["De tawhied","De hadj","De soenna","De fiqh"],b:0,e:"De tawhied is het hart van het islamitische geloof.",s:['q:112:1']},
  {q:"Welke soera vat de eenheid van Allah samen in vier verzen?",c:["Al-Ikhlas","Al-Fatiha","Al-Kawthar","An-Nas"],b:0,e:"Soera 112, Al-Ikhlas.",s:['q:112:1']},
  {q:"Uit hoeveel delen bestaat de sjahada?",c:["Twee: de eenheid van Allah en de boodschap van Mohammed ﷺ","Eén","Vijf","Zeven"],b:0,e:"Men getuigt van de eenheid van Allah en daarna dat Mohammed ﷺ Zijn Boodschapper is.",s:['h:piliers']},
  {q:"Heeft Allah volgens soera Al-Ikhlas verwekt of is Hij verwekt?",c:["Geen van beide","Allebei","Hij heeft verwekt","Hij is verwekt"],b:0,e:"“Hij verwekt niet en is niet verwekt.”",s:['q:112:3']},
  {q:"Wat betekent “Ash-hadu” aan het begin van de sjahada?",c:["Ik getuig","Ik bid","Ik vast","Ik vergeef"],b:0,e:"Ash-hadu betekent “ik getuig, ik leg getuigenis af”.",s:['f:shahada']},
  {q:"Wat doet iemand om tot de islam toe te treden?",c:["Hij spreekt de sjahada uit met overtuiging","Hij vast een maand","Hij verricht de hadj","Hij leert Arabisch"],b:0,e:"De oprecht uitgesproken sjahada laat iemand tot de islam toetreden.",s:['f:shahada']},
  {q:"Wat zegt de Koran over Mohammed ﷺ in soera Al ʿImran, vers 144?",c:["Hij is slechts een boodschapper; vóór hem zijn er andere boodschappers voorbijgegaan","Hij is eeuwig","Hij is een engel","Hij is de eerste profeet"],b:0,e:"Mohammed ﷺ is een mens en een boodschapper, net als zij die hem voorgingen.",s:['q:3:144']}
 ]},
'p-priere':{titre:"Het gebed, vijf afspraken per dag",
 texte:["De moslim bidt vijf keer per dag: Fadjr bij de dageraad, Dhohr rond het middaguur, ʿAsr in de namiddag, Maghrib bij zonsondergang en ʿIshaa' in de nacht.",
  "Elk gebed telt een vast aantal eenheden (rakʿat): 2 voor Fadjr, 4 voor Dhohr, 4 voor ʿAsr, 3 voor Maghrib en 4 voor ʿIshaa'.",
  "Men bidt gericht naar de Kaaba in Mekka: dat is de qibla. Het tijdstip van elk gebed wordt aangekondigd met de adhan. Op vrijdag wordt het Dhohr-gebed vervangen door het vrijdaggebed (Djumuʿa)."],
 retenir:"Fadjr 2, Dhohr 4, ʿAsr 4, Maghrib 3, ʿIshaa' 4 — gericht naar de qibla.",
 sources:['q:4:103','f:rakat','q:2:144'],
 quiz:[
  {q:"Hoeveel eenheden (rakʿat) telt het verplichte Fadjr-gebed?",c:["2","3","4","1"],b:0,e:"Het Fadjr-gebed telt 2 rakʿat.",s:['f:rakat']},
  {q:"Hoeveel eenheden (rakʿat) telt het verplichte Maghrib-gebed?",c:["3","2","4","5"],b:0,e:"Maghrib is het enige verplichte gebed met 3 rakʿat.",s:['f:rakat']},
  {q:"In welke richting keren moslims zich om te bidden?",c:["Naar de Kaaba in Mekka","Naar Jeruzalem","Naar Medina","Naar het oosten"],b:0,e:"Deze richting heet de qibla.",s:['q:2:144']},
  {q:"Hoe heet de oproep die het tijdstip van het gebed aankondigt?",c:["De adhan","De iqama","De doeʿa","De dhikr"],b:0,e:"De adhan kondigt het tijdstip aan; de iqama kondigt het begin van het gezamenlijke gebed aan.",s:['h:adhan']},
  {q:"Hoe heet het verplichte gebed bij de dageraad?",c:["Fadjr","Dhohr","ʿAsr","ʿIshaa'"],b:0,e:"Fadjr wordt gebeden tussen de dageraad en zonsopgang.",s:['f:rakat']},
  {q:"Hoeveel eenheden (rakʿat) telt het verplichte Dhohr-gebed?",c:["4","2","3","5"],b:0,e:"Dhohr telt 4 rakʿat.",s:['f:rakat']},
  {q:"Hoeveel verplichte eenheden (rakʿat) tellen de vijf gebeden van één dag samen?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 rakʿat.",s:['f:rakat']},
  {q:"Hoe werd het gebed volgens de Koran aan de gelovigen voorgeschreven?",c:["Op vastgestelde tijden","Eén keer per week","Wanneer men wil","Alleen tijdens Ramadan"],b:0,e:"“Voorwaar, het gebed is voor de gelovigen een voorschrift op vastgestelde tijden.”",s:['q:4:103']},
  {q:"Welk gezamenlijk gebed vindt elke vrijdag plaats in plaats van Dhohr?",c:["Het vrijdaggebed (Djumuʿa)","Het feestgebed","De tarawih","Het gebed om regen"],b:0,e:"De Koran roept op om op vrijdag naar het gedenken van Allah te gaan.",s:['q:62:9']},
  {q:"Bij welke gebeurtenis werden volgens de hadith de vijf gebeden voorgeschreven?",c:["De Nachtreis (al-Israa' wal-Miʿradj)","De slag bij Badr","De Hidjra","De verovering van Mekka"],b:0,e:"Er werden vijftig gebeden voorgeschreven, die daarna tot vijf werden teruggebracht.",s:['h:cinq']}
 ]},
'p-ablutions':{titre:"De wassing en de Fatiha",
 texte:["Voor het gebed reinigt de moslim zich met water: dat is de kleine wassing (woedoe). Zonder water doet men tayammum met schone aarde.",
  "Men wast het gezicht, de handen en onderarmen tot aan de ellebogen, men strijkt met natte handen over het hoofd en wast daarna de voeten tot aan de enkels.",
  "In elke eenheid van het gebed reciteert men soera Al-Fatiha, “de Opening”, de eerste soera van de Koran, die 7 verzen telt."],
 retenir:"Geen gebed zonder wassing, geen gebed zonder de Fatiha.",
 sources:['q:5:6','q:1:2','h:fatiha'],
 quiz:[
  {q:"Hoe heet de reiniging met water vóór het gebed?",c:["De wassing (woedoe)","Het vasten","De zakat","De iʿtikaf"],b:0,e:"De woedoe reinigt vóór het gebed.",s:['q:5:6']},
  {q:"Welke soera wordt in elke eenheid (rakʿa) van het gebed gereciteerd?",c:["Al-Fatiha","Al-Ikhlas","Al-Baqara","Ya-Sin"],b:0,e:"Al-Fatiha, “de Opening”, wordt in elke rakʿa gereciteerd.",s:['h:fatiha']},
  {q:"Met welke zin begint soera Al-Fatiha?",c:["Bismi Llâhi r-Raḥmâni r-Raḥîm","Qul huwa Llâhu aḥad","Allâhu akbar","Subḥâna Llâh"],b:0,e:"“In de naam van Allah, de Barmhartige, de Genadevolle.”",s:['q:1:1']},
  {q:"Tot waar wast men volgens de Koran de armen tijdens de wassing?",c:["Tot aan de ellebogen","Tot aan de polsen","Tot aan de schouders","Alleen de vingers"],b:0,e:"Vers 6 van soera Al-Maida zegt dit.",s:['q:5:6']},
  {q:"Wat doet men volgens de Koran met het hoofd tijdens de wassing?",c:["Men strijkt er met natte handen over","Men wast het drie keer volledig","Men bedekt het met een tulband","Men giet water over de nek"],b:0,e:"Dat is de mas-h: met natte handen over het hoofd strijken.",s:['q:5:6']},
  {q:"Wat doet men als men geen water vindt om zich vóór het gebed te reinigen?",c:["Tayammum, met schone aarde","Men bidt niet","Men wacht tot de volgende dag","Men bidt zonder reiniging"],b:0,e:"Hetzelfde vers voorziet in tayammum als er geen water is.",s:['q:5:6']},
  {q:"Aanvaardt Allah volgens de hadith het gebed van iemand die zijn wassing heeft verloren en die niet opnieuw heeft gedaan?",c:["Nee, niet voordat hij de wassing opnieuw doet","Ja, altijd","Ja, op vrijdag","Alleen het Fadjr-gebed"],b:0,e:"Het gebed wordt pas aanvaard nadat men de wassing opnieuw heeft gedaan.",s:['h:wudu']},
  {q:"Hoeveel verzen telt soera Al-Fatiha?",c:["7","5","10","3"],b:0,e:"Ze wordt “de zeven herhaalde verzen” genoemd.",s:['q:15:87']},
  {q:"Wat betekent “Al-ḥamdu li-Llâhi rabbi l-ʿâlamîn”?",c:["Alle lof zij Allah, de Heer der werelden","Allah is de Grootste","Er is geen god dan Allah","Ik zoek mijn toevlucht bij Allah"],b:0,e:"Dat is het 2e vers van de Fatiha.",s:['q:1:2']},
  {q:"Wat is volgens de hadith het gebed waard van iemand die de Fatiha niet reciteert?",c:["Het is niet geldig","Het telt dubbel","Het is geldig","Het telt half"],b:0,e:"“Er is geen gebed voor wie de Fatiha niet reciteert.”",s:['h:fatiha']}
 ]},
'p-zakat':{titre:"De zakat, de verplichte aalmoes",
 texte:["De zakat is de verplichte aalmoes, een van de vijf zuilen van de islam. De naam verwijst naar zuivering en groei: ze zuivert de bezittingen en helpt de armsten.",
  "Ze geldt voor wie spaargeld heeft dat een minimumdrempel (de nisab) bereikt en dat een volledig maanjaar in zijn bezit blijft. Voor geld bedraagt ze 2,5%.",
  "De Koran noemt acht categorieën ontvangers, onder wie de armen en de behoeftigen. De sadaqa is daarentegen een vrijwillige aalmoes, die op elk moment kan worden gegeven."],
 retenir:"Zakat: 2,5% van het spaargeld dat een maanjaar lang de nisab bereikt.",
 sources:['q:9:60','q:9:103','f:zakat'],
 quiz:[
  {q:"Welke zuil van de islam is de verplichte aalmoes?",c:["De zakat","De sadaqa","De hadj","De sawm"],b:0,e:"De zakat is verplicht; de sadaqa is vrijwillig.",s:['h:piliers']},
  {q:"Hoeveel bedraagt de zakat over gespaard geld?",c:["2,5%","10%","20%","5%"],b:0,e:"Dat is een veertigste van het spaargeld.",s:['f:zakat']},
  {q:"Hoe heet de minimumdrempel van rijkdom vanaf welke de zakat verschuldigd is?",c:["De nisab","De saʿ","De fidya","De hawl"],b:0,e:"Onder de nisab is de zakat niet verplicht.",s:['f:zakat']},
  {q:"Hoe lang moet het spaargeld in bezit zijn voordat de zakat verschuldigd is?",c:["Een maanjaar","Een maand","Tien jaar","Alleen de maand Ramadan"],b:0,e:"Dat is de hawl: een volledig maanjaar.",s:['f:zakat']},
  {q:"Hoeveel categorieën mensen mogen volgens de Koran de zakat ontvangen?",c:["8","5","3","12"],b:0,e:"Vers 60 van soera At-Tawba noemt er acht.",s:['q:9:60']},
  {q:"Wie horen bij de ontvangers van de zakat die in de Koran worden genoemd?",c:["De armen en de behoeftigen","De rijksten","De handelaars","De imams van de moskeeën"],b:0,e:"De armen en de behoeftigen worden als eersten genoemd.",s:['q:9:60']},
  {q:"Wat is het verschil tussen de zakat en de sadaqa?",c:["De zakat is verplicht, de sadaqa is vrijwillig","Er is geen verschil","De sadaqa is verplicht","De zakat is verboden"],b:0,e:"De sadaqa kan op elk moment en in elke hoeveelheid worden gegeven.",s:['f:zakat']},
  {q:"Met welke daad wordt de zakat in de Koran heel vaak samen genoemd?",c:["Het gebed","Het vasten","De bedevaart","De wassing"],b:0,e:"“Verricht het gebed en geef de zakat”: deze formule komt vele malen terug.",s:['q:2:43']},
  {q:"Op welke plaats staat de zakat in de volgorde van de hadith over de zuilen?",c:["De 3e","De 1e","De 5e","De 2e"],b:0,e:"Sjahada, gebed, zakat, hadj, het vasten van Ramadan.",s:['h:piliers']},
  {q:"Waar verwijst het Arabische woord “zakat” naar?",c:["Zuivering en groei","Geduld","Overwinning","Licht"],b:0,e:"De Koran zegt dat de aalmoes zuivert (tutahhiruhum) en doet groeien in het goede (tuzakkihim).",s:['q:9:103']}
 ]},
'p-hajj':{titre:"De hadj, de bedevaart",
 texte:["De hadj is de bedevaart naar Mekka, een van de vijf zuilen van de islam. Hij is één keer in het leven verplicht voor wie er lichamelijk en financieel toe in staat is.",
  "Hij vindt plaats in de maand Dhul-Hiddja. De pelgrim treedt in de gewijde staat (ihram), loopt zeven rondes om de Kaaba (tawaf) en legt zeven keer de weg af tussen Safa en Marwa (saʿy). Het belangrijkste moment is het verblijf op ʿArafa, op 9 Dhul-Hiddja.",
  "De dag erna vieren moslims over de hele wereld het Offerfeest (Eid al-Adha), ter herinnering aan Ibrahim."],
 retenir:"Eén keer in het leven. ʿArafa op 9 Dhul-Hiddja, het Offerfeest op de 10e.",
 sources:['q:3:97','q:22:27','h:hajj_pardon'],
 quiz:[
  {q:"In welke stad wordt de hadj verricht?",c:["Mekka","Medina","Jeruzalem","Taʾif"],b:0,e:"De hadj wordt verricht in Mekka en omgeving.",s:['q:3:97']},
  {q:"In welke maand van de islamitische kalender vindt de hadj plaats?",c:["Dhul-Hiddja","Ramadan","Muharram","Sjawwal"],b:0,e:"De hadj vindt plaats van 8 tot 13 Dhul-Hiddja.",s:['f:hajj']},
  {q:"Wat is volgens de hadith het belangrijkste onderdeel van de hadj?",c:["Het verblijf op ʿArafa","Het gebed in de al-Aqsa-moskee","Het bezoek aan Medina","Het bezoek aan de grot Hira"],b:0,e:"“De hadj is ʿArafa.”",s:['h:arafa']},
  {q:"Welk feest wordt gevierd op de dag na de dag van ʿArafa?",c:["Het Offerfeest (Eid al-Adha)","Het Suikerfeest (Eid al-Fitr)","De Mawlid","1 Muharram"],b:0,e:"Op 10 Dhul-Hiddja is het Offerfeest.",s:['f:hajj']},
  {q:"Hoe keert volgens de hadith de pelgrim terug die de hadj verricht zonder zonde en zonder grofheid?",c:["Zoals op de dag dat zijn moeder hem baarde","Rijker","Vrijgesteld van vasten","Met de titel hadji, zonder andere beloning"],b:0,e:"Hij keert terug, gezuiverd van zijn zonden.",s:['h:hajj_pardon']},
  {q:"Welke profeet kreeg het bevel om de mensen op te roepen tot de bedevaart?",c:["Ibrahim","Moesa","Noeh","Yoesoef"],b:0,e:"Allah beval Ibrahim om de mensen op te roepen tot de hadj.",s:['q:22:27']},
  {q:"Hoe heet de gewijde staat waarin de pelgrim treedt?",c:["De ihram","De woedoe","De iʿtikaf","De tayammum"],b:0,e:"Mannen dragen twee ongenaaide witte doeken.",s:['f:hajj']},
  {q:"Hoe heten de zeven rondes die om de Kaaba worden gelopen?",c:["De tawaf","De saʿy","De rakʿa","De dhikr"],b:0,e:"De tawaf bestaat uit zeven rondes, met de Kaaba aan de linkerkant.",s:['f:hajj']},
  {q:"Tussen welke twee heuvels legt de pelgrim zeven keer de weg af?",c:["Safa en Marwa","ʿArafa en Mina","Uhud en Thawr","Hira en Thawr"],b:0,e:"De Koran noemt Safa en Marwa onder de riten van Allah.",s:['q:2:158']},
  {q:"Ter herinnering aan welke profeet slachten moslims een dier op de dag van het Offerfeest?",c:["Ibrahim","ʿIsa","Moesa","Dawoed"],b:0,e:"Allah kocht de zoon van Ibrahim vrij met een groots offer.",s:['q:37:107']}
 ]},

/* ===================== KORAN ===================== */
'c-coran':{titre:"De Koran, het woord van Allah",
 texte:["De Koran is het woord van Allah, in het Arabisch geopenbaard aan de Profeet Mohammed ﷺ via de engel Djibriel (Gabriël).",
  "De eerste openbaring vond plaats in de grot Hira, bij Mekka, toen de Profeet ﷺ 40 jaar oud was. De eerste geopenbaarde woorden beginnen met “Iqra'”: “Lees!”.",
  "De openbaring duurde ongeveer 23 jaar. De Koran telt 114 soera's; Allah heeft beloofd hem te bewaren."],
 retenir:"114 soera's, geopenbaard in 23 jaar. Eerste woord: “Iqra'”, “Lees!”.",
 sources:['q:96:1','h:hira','q:15:9'],
 quiz:[
  {q:"Hoeveel soera's telt de Koran?",c:["114","99","120","30"],b:0,e:"De Koran telt 114 soera's.",s:['f:coran']},
  {q:"Welke engel bracht de Koran over aan de Profeet Mohammed ﷺ?",c:["Djibriel (Gabriël)","Mikaʾiel","Israfiel","Malik"],b:0,e:"Het was de engel Djibriel die de openbaring overbracht.",s:['q:2:97']},
  {q:"In welke grot ontving de Profeet ﷺ de eerste openbaring van de Koran?",c:["De grot Hira","De grot Thawr","Een grot in Medina","Een grot in Jeruzalem"],b:0,e:"De grot Hira ligt op de Djabal an-Noer, bij Mekka.",s:['h:hira']},
  {q:"Wat betekent “Iqra'”, het eerste geopenbaarde woord van de Koran?",c:["Lees!","Bid!","Luister!","Vast!"],b:0,e:"Het is het begin van soera Al-ʿAlaq (96).",s:['q:96:1']},
  {q:"Over hoeveel jaar ongeveer werd de Koran geopenbaard?",c:["23 jaar","1 jaar","40 jaar","10 jaar"],b:0,e:"Ongeveer 13 jaar in Mekka en 10 jaar in Medina.",s:['h:vie']},
  {q:"In hoeveel delen (djuzʾ) is de Koran verdeeld om te lezen?",c:["30","114","7","12"],b:0,e:"Dertig delen: bijvoorbeeld één per dag tijdens Ramadan.",s:['f:coran']},
  {q:"In welke taal werd de Koran geopenbaard?",c:["In het Arabisch","In het Hebreeuws","In het Perzisch","In het Aramees"],b:0,e:"“Wij hebben hem neergezonden als een Arabische Koran.”",s:['q:12:2']},
  {q:"Wie zorgt volgens de Koran voor het bewaren van de Koran?",c:["Allah","Alleen de geleerden","De kaliefen","Niemand"],b:0,e:"“Wij hebben de Vermaning neergezonden en Wij zijn er de Bewaarders van.”",s:['q:15:9']},
  {q:"Hoe oud was de Profeet ﷺ bij de eerste openbaring?",c:["40 jaar","25 jaar","63 jaar","13 jaar"],b:0,e:"Hij begon de openbaring te ontvangen op 40-jarige leeftijd.",s:['h:vie']},
  {q:"Hoe heet een vers van de Koran in het Arabisch?",c:["Een aya","Een soera","Een djuzʾ","Een hadith"],b:0,e:"Een vers heet aya; een hoofdstuk heet soera.",s:['f:coran']}
 ]},
'c-sourates':{titre:"De soera's",
 texte:["De Koran bestaat uit 114 soera's van zeer verschillende lengte. Elke soera begint met de basmala, behalve soera At-Tawba.",
  "De eerste is Al-Fatiha, “de Opening”. De langste is Al-Baqara, “de Koe”, met 286 verzen. De kortste is Al-Kawthar, met 3 verzen. De laatste is An-Nas, “de Mensen”.",
  "De soera's die vóór de Hidjra werden geopenbaard, heten Mekkaans; die erna Medinensisch."],
 retenir:"Eerste: Al-Fatiha. Langste: Al-Baqara. Kortste: Al-Kawthar. Laatste: An-Nas.",
 sources:['q:1:1','q:108:1','q:114:1'],
 quiz:[
  {q:"Wat is de eerste soera van de Koran?",c:["Al-Fatiha","Al-Baqara","An-Nas","Al-ʿAlaq"],b:0,e:"Al-Fatiha opent de Koran. Al-ʿAlaq bevat de eerste geopenbaarde verzen, maar is soera 96.",s:['q:1:1']},
  {q:"Wat is de langste soera van de Koran?",c:["Al-Baqara","Al-Fatiha","Al-Kawthar","Ya-Sin"],b:0,e:"Al-Baqara, soera 2, telt 286 verzen.",s:['f:coran']},
  {q:"Wat is de kortste soera van de Koran?",c:["Al-Kawthar","Al-Ikhlas","An-Nas","Al-ʿAsr"],b:0,e:"Al-Kawthar, soera 108, telt 3 verzen.",s:['q:108:1']},
  {q:"Wat is de laatste soera van de Koran?",c:["An-Nas","Al-Falaq","Al-Ikhlas","Al-Fatiha"],b:0,e:"An-Nas, “de Mensen”, is soera 114.",s:['q:114:1']},
  {q:"Welke soera begint met “Qul huwa Llâhu aḥad”?",c:["Al-Ikhlas","An-Nas","Al-Falaq","Al-Kafiroen"],b:0,e:"“Zeg: Hij is Allah, de Ene.”",s:['q:112:1']},
  {q:"Welke soera bevat het vers “Dit is het Boek waaraan geen twijfel is”?",c:["Al-Baqara","Al-Fatiha","Maryam","Ya-Sin"],b:0,e:"Het is het 2e vers van soera Al-Baqara.",s:['q:2:2']},
  {q:"Welke soera draagt de naam van de moeder van ʿIsa (Jezus)?",c:["Maryam","Al ʿImran","An-Nisaʾ","Ta-Ha"],b:0,e:"Soera 19 draagt de naam van Maryam.",s:['q:19:16']},
  {q:"Wat is de enige soera die niet begint met “Bismi Llâhi r-Raḥmâni r-Raḥîm”?",c:["At-Tawba (soera 9)","Al-Fatiha","An-Nas","Al-Baqara"],b:0,e:"At-Tawba is de enige van de 114 soera's zonder basmala aan het begin.",s:['f:tawba']},
  {q:"Hoe heet de formule “Bismi Llâhi r-Raḥmâni r-Raḥîm”?",c:["De basmala","De sjahada","De takbier","De talbiya"],b:0,e:"Ze betekent: “In de naam van Allah, de Barmhartige, de Genadevolle”.",s:['q:1:1']},
  {q:"Hoe heten de soera's die vóór de Hidjra in Mekka werden geopenbaard?",c:["De Mekkaanse soera's","De Medinensische soera's","De lange soera's","De soera's van Taʾif"],b:0,e:"Die na de Hidjra werden geopenbaard, heten Medinensisch.",s:['f:coran']}
 ]},
'c-ikhlas':{titre:"Al-Ikhlas en het Troonvers",
 texte:["Soera Al-Ikhlas (112) vat het geloof in de eenheid van Allah samen: Hij is de Ene, Hij verwekt niet en is niet verwekt, en niemand is aan Hem gelijk.",
  "De Profeet ﷺ zei dat ze gelijkstaat aan een derde van de Koran.",
  "Het Troonvers, Ayat al-Koersi (soera 2, vers 255), is het grootste vers van de Koran. Het beschrijft het leven, de kennis en de macht van Allah."],
 retenir:"Al-Ikhlas is een derde van de Koran waard. Ayat al-Koersi is het grootste vers.",
 sources:['q:112:1','h:ikhlas','h:kursi'],
 quiz:[
  {q:"Wat betekent “Qul huwa Llâhu aḥad”?",c:["Zeg: Hij is Allah, de Ene","In de naam van Allah","Allah is de Grootste","Glorie aan Allah"],b:0,e:"Het is het eerste vers van soera Al-Ikhlas.",s:['q:112:1']},
  {q:"Met welk deel van de Koran staat soera Al-Ikhlas volgens de hadith gelijk?",c:["Een derde","De helft","Een tiende","De hele Koran"],b:0,e:"De Profeet ﷺ zei dat ze gelijkstaat aan een derde van de Koran.",s:['h:ikhlas']},
  {q:"Hoeveel verzen telt soera Al-Ikhlas?",c:["4","7","3","5"],b:0,e:"Soera Al-Ikhlas telt 4 verzen.",s:['q:112:4']},
  {q:"Is er volgens soera Al-Ikhlas iemand aan Allah gelijk?",c:["Nee, niemand is aan Hem gelijk","Ja, de engelen","Ja, de profeten","Ja, de djinn"],b:0,e:"“En niemand is aan Hem gelijk.”",s:['q:112:4']},
  {q:"Wat is volgens de hadith het grootste vers van de Koran?",c:["Ayat al-Koersi, het Troonvers","Het eerste vers van de Fatiha","Het laatste vers van de Koran","Het Lichtvers"],b:0,e:"Ubayy ibn Kaʿb zei het tegen de Profeet ﷺ, die het bevestigde.",s:['h:kursi']},
  {q:"In welke soera staat Ayat al-Koersi?",c:["Al-Baqara, vers 255","Al-Fatiha, vers 1","Ya-Sin, vers 1","Al-Ikhlas, vers 2"],b:0,e:"Het Troonvers is het 255e vers van soera Al-Baqara.",s:['q:2:255']},
  {q:"Wordt Allah volgens Ayat al-Koersi door sluimer of slaap overmand?",c:["Nee, sluimer noch slaap overmant Hem","Ja, 's nachts","Ja, soms","Alleen door slaap"],b:0,e:"Allah is de Levende, Degene Die door Zichzelf bestaat.",s:['q:2:255']},
  {q:"Wat betekent “Allâhu ṣ-ṣamad” in soera Al-Ikhlas?",c:["Allah is Degene aan Wie allen behoefte hebben en Die niemand nodig heeft","Allah is de Schepper van de hemel","Allah is de Vergever","Allah is de Rechter"],b:0,e:"As-Samad is een van de namen van Allah.",s:['q:112:2']},
  {q:"Wat betekent de naam van soera “Al-Ikhlas”?",c:["Het zuivere monotheïsme, de oprechtheid","De dageraad","De overwinning","De mensen"],b:0,e:"Ze zuivert het geloof van elke vorm van afgoderij.",s:['f:ikhlas']},
  {q:"Wat geeft Allah volgens Ayat al-Koersi aan Zijn schepselen van Zijn kennis?",c:["Alleen wat Hij wil","Al Zijn kennis","Helemaal niets","De helft"],b:0,e:"“En zij omvatten niets van Zijn kennis, behalve wat Hij wil.”",s:['q:2:255']}
 ]},

/* ===================== PROFETEN ===================== */
'pr-adam':{titre:"Adam en Noeh",
 texte:["Adam is de eerste mens en de eerste profeet. Allah leerde hem de namen van alle dingen en beval daarna de engelen om zich voor hem neer te werpen. Iblies weigerde uit hoogmoed.",
  "Noeh (Noach) riep zijn volk 950 jaar lang op om Allah alleen te aanbidden. Weinig mensen volgden hem, zelfs zijn eigen zoon niet.",
  "Op bevel van Allah bouwde Noeh de ark, die hem met de gelovigen en paren dieren redde van de zondvloed."],
 retenir:"Adam, de eerste mens. Noeh, 950 jaar prediking, en de ark.",
 sources:['q:2:31','q:2:34','q:29:14'],
 quiz:[
  {q:"Wie is de eerste profeet van de mensheid?",c:["Adam","Noeh (Noach)","Ibrahim (Abraham)","Moesa (Mozes)"],b:0,e:"Adam is de eerste mens en de eerste profeet.",s:['q:2:31']},
  {q:"Wat heeft Allah aan Adam geleerd?",c:["De namen van alle dingen","De Koran uit het hoofd","Alleen de taal van de engelen","Alleen de namen van de profeten"],b:0,e:"“En Hij leerde Adam alle namen.”",s:['q:2:31']},
  {q:"Wie weigerde zich voor Adam neer te werpen?",c:["Iblies","Djibriel","Mikaʾiel","Alle engelen"],b:0,e:"De engelen wierpen zich neer, behalve Iblies.",s:['q:2:34']},
  {q:"Waarom weigerde Iblies zich voor Adam neer te werpen?",c:["Uit hoogmoed","Uit vergetelheid","Uit angst","Omdat hij het bevel niet had gehoord"],b:0,e:"Hij weigerde, werd hoogmoedig en behoorde tot de ongelovigen.",s:['q:2:34']},
  {q:"Waar woonden Adam en zijn vrouw voordat ze naar de aarde afdaalden?",c:["In het Paradijs","In Mekka","In Egypte","In Jeruzalem"],b:0,e:"“Woon in het Paradijs, jij en je vrouw.”",s:['q:2:35']},
  {q:"Welke profeet bouwde op bevel van Allah de ark?",c:["Noeh (Noach)","Yoenoes (Jona)","Soeleiman (Salomo)","ʿIsa (Jezus)"],b:0,e:"Noeh bouwde de ark onder het oog van Allah en volgens Zijn openbaring.",s:['q:11:37']},
  {q:"Hoe lang bleef Noeh volgens de Koran onder zijn volk?",c:["950 jaar","40 jaar","100 jaar","313 jaar"],b:0,e:"“Duizend jaar min vijftig jaar.”",s:['q:29:14']},
  {q:"Wie werden gered in de ark van Noeh?",c:["Noeh, de gelovigen en paren dieren","Zijn hele volk","Alleen de dieren","Niemand"],b:0,e:"Allah beval er een paar van elke soort, zijn familie en de gelovigen in te laten.",s:['q:11:40']},
  {q:"Is de zoon van Noeh in de ark gestapt?",c:["Nee, hij weigerde en verdronk","Ja, als eerste","Ja, als laatste","Hij had geen zoon"],b:0,e:"Hij dacht te kunnen schuilen op een berg, maar de golven sleurden hem mee.",s:['q:11:43']},
  {q:"Hoe heet de vrouw van Adam volgens de islamitische overlevering?",c:["Hawwa (Eva)","Maryam","Asiya","Hadjar"],b:0,e:"De Koran noemt haar zonder haar naam te geven; haar naam komt uit de soenna.",s:['f:hawwa']}
 ]},
'pr-ibrahim':{titre:"Ibrahim, de vriend van Allah",
 texte:["Ibrahim (Abraham) weigerde de afgoden van zijn volk te aanbidden. Hij werd in een groot vuur geworpen, maar Allah beval het vuur koel en veilig voor hem te zijn.",
  "Allah nam hem als intieme vriend (khalil). Hij is de vader van twee profeten: Ismaʿiel en Ishaq.",
  "Samen met zijn zoon Ismaʿiel richtte hij de fundamenten van de Kaaba op. Het offer van het Offerfeest herinnert aan zijn gehoorzaamheid aan Allah."],
 retenir:"Ibrahim, de vriend van Allah, gered uit het vuur, bouwer van de Kaaba met Ismaʿiel.",
 sources:['q:21:69','q:4:125','q:2:127'],
 quiz:[
  {q:"Welke profeet richtte samen met zijn zoon Ismaʿiel de fundamenten van de Kaaba op?",c:["Ibrahim (Abraham)","Moesa (Mozes)","Dawoed (David)","Adam"],b:0,e:"Ibrahim en zijn zoon Ismaʿiel richtten de fundamenten van de Kaaba op.",s:['q:2:127']},
  {q:"Wat gebeurde er met Ibrahim toen zijn volk hem in het vuur wierp?",c:["Allah maakte het vuur koel en ongevaarlijk voor hem","Hij vluchtte","Hij raakte gewond","Hij werd gered door de regen"],b:0,e:"“O vuur, wees koel en veilig voor Ibrahim.”",s:['q:21:69']},
  {q:"Welke titel geeft de Koran aan de profeet Ibrahim?",c:["De intieme vriend van Allah (Khalil)","Het zegel der profeten","Degene tot wie Allah sprak","De Geest van Allah"],b:0,e:"“En Allah nam Ibrahim als vriend.”",s:['q:4:125']},
  {q:"Wie zijn de twee zonen van Ibrahim die profeet waren?",c:["Ismaʿiel en Ishaq","Moesa en Haroen","Dawoed en Soeleiman","Yahya en ʿIsa"],b:0,e:"Ibrahim dankte Allah omdat Hij hem op hoge leeftijd Ismaʿiel en Ishaq schonk.",s:['q:14:39']},
  {q:"Wat deed het volk van Ibrahim, wat hij weigerde?",c:["Beelden aanbidden","Vasten","Aalmoezen geven","Op bedevaart gaan"],b:0,e:"Hij vroeg hun: “Wat zijn dit voor beelden waaraan jullie zo gehecht zijn?”",s:['q:21:52']},
  {q:"Waarmee kocht Allah de zoon van Ibrahim vrij op het moment van het offer?",c:["Met een groots offer (een offerdier)","Met een aalmoes van goud","Met het vasten van zijn vader","Met een nachtgebed"],b:0,e:"De overlevering verduidelijkt dat het om een ram ging.",s:['q:37:107']},
  {q:"Welk feest herinnert aan de gehoorzaamheid van Ibrahim aan Allah?",c:["Het Offerfeest (Eid al-Adha)","Het Suikerfeest (Eid al-Fitr)","1 Muharram","De Mawlid"],b:0,e:"Het offer van het Offerfeest herdenkt zijn beproeving.",s:['q:37:107']},
  {q:"Hoe wordt Ibrahim volgens de Koran beschreven?",c:["Een monotheïstische gelovige (hanief), noch jood noch christen","Een koning van Babylon","Een engel","Een dichter"],b:0,e:"Hij was volledig overgegeven aan Allah.",s:['q:3:67']},
  {q:"Welke zoon hielp Ibrahim de fundamenten van de Kaaba op te richten?",c:["Ismaʿiel","Ishaq","Yaʿqoeb","Yoesoef"],b:0,e:"Ibrahim en Ismaʿiel richtten samen de fundamenten van het Huis op.",s:['q:2:127']},
  {q:"Wat is volgens de Koran het eerste Huis van aanbidding dat voor de mensen werd gesticht?",c:["Dat in Bakka (Mekka)","Dat in Jeruzalem","Dat in Medina","Dat in Taʾif"],b:0,e:"Bakka is een naam van Mekka.",s:['q:3:96']}
 ]},
'pr-yunus':{titre:"Yoenoes, Yoesoef en Soeleiman",
 texte:["Yoenoes (Jona) werd door een grote vis opgeslokt. In de duisternis riep hij Allah aan, Die hem uit zijn benauwdheid redde.",
  "Het verhaal van Yoesoef (Jozef), die door zijn broers werd verraden en later minister in Egypte werd, beslaat heel soera 12: “het mooiste verhaal”.",
  "Soeleiman (Salomo), zoon van Dawoed, kreeg een enorm koninkrijk en verstond de taal van de vogels en de mieren."],
 retenir:"Yoenoes en de vis. Yoesoef, soera 12. Soeleiman en de taal van de dieren.",
 sources:['q:37:142','q:12:3','q:27:18'],
 quiz:[
  {q:"Welke profeet werd door een grote vis opgeslokt?",c:["Yoenoes (Jona)","Yoesoef (Jozef)","Ayyoeb (Job)","Loet (Lot)"],b:0,e:"Yoenoes werd door de vis opgeslokt, daarna redde Allah hem.",s:['q:37:142']},
  {q:"Welke soera van de Koran vertelt het volledige verhaal van de profeet Yoesoef (Jozef)?",c:["Soera 12, Yoesoef","Soera 1, Al-Fatiha","Soera 36, Ya-Sin","Soera 112, Al-Ikhlas"],b:0,e:"Soera 12 draagt zijn naam.",s:['q:12:3']},
  {q:"Welke profeet verstond de taal van de mieren?",c:["Soeleiman (Salomo)","Salih","Hoed","Zakariyya"],b:0,e:"Soeleiman hoorde een mier de andere waarschuwen en glimlachte om haar woorden.",s:['q:27:18']},
  {q:"Welke smeekbede sprak Yoenoes uit in de buik van de vis?",c:["“Lâ ilâha illâ anta, subḥânaka, innî kuntu mina ẓ-ẓâlimîn”","“Bismi Llâh”","“Allâhu akbar”","“Rabbanâ âtinâ”"],b:0,e:"“Er is geen god dan U! Glorie aan U! Ik behoorde werkelijk tot de onrechtplegers.”",s:['q:21:87']},
  {q:"Hoe antwoordde Allah op de smeekbede van Yoenoes?",c:["Hij redde hem uit zijn benauwdheid","Hij liet hem in de vis","Hij liet hem drie jaar in de vis","Hij antwoordde niet"],b:0,e:"“Wij verhoorden hem en redden hem uit de benauwdheid.”",s:['q:21:88']},
  {q:"Hoeveel sterren zag Yoesoef in zijn droom als kind zich voor hem neerwerpen?",c:["Elf, met de zon en de maan","Zeven","Twaalf","Eén"],b:0,e:"Elf sterren, de zon en de maan.",s:['q:12:4']},
  {q:"Wie wierp Yoesoef in een put?",c:["Zijn broers","Farao","Handelaars","Zijn vader"],b:0,e:"Zijn jaloerse broers besloten hem op de bodem van de put te werpen.",s:['q:12:15']},
  {q:"Hoe noemt de Koran het verhaal van Yoesoef?",c:["Het mooiste verhaal","Het verhaal van het vuur","Het boek van de wijsheid","Het verhaal van de ark"],b:0,e:"“Wij vertellen jou het mooiste verhaal.”",s:['q:12:3']},
  {q:"Welke profeet kreeg kennis van de taal van de vogels?",c:["Soeleiman","Yoenoes","Noeh","Hoed"],b:0,e:"“Ons is de taal van de vogels geleerd”, zei Soeleiman.",s:['q:27:16']},
  {q:"Wie was de vader van Soeleiman, die ook profeet en koning was?",c:["Dawoed (David)","Ibrahim","Yaʿqoeb","Moesa"],b:0,e:"“En Soeleiman erfde van Dawoed.”",s:['q:27:16']}
 ]},
'pr-musa':{titre:"Moesa, degene tot wie Allah sprak",
 texte:["Moesa (Mozes) werd geboren in Egypte, in de tijd dat Farao de Banoe Israʾiel vervolgde. Door ingeving van Allah legde zijn moeder hem op de rivier, en de familie van Farao nam hem op.",
  "Allah sprak rechtstreeks tot hem en zond hem samen met zijn broer Haroen naar Farao, met wonderen, zoals zijn staf die een slang werd.",
  "Allah spleet de zee om Moesa en zijn volk te redden, en Farao verdronk. Moesa is de profeet die het vaakst in de Koran wordt genoemd."],
 retenir:"Moesa, gered uit het water, Kalim Allah, de gespleten zee.",
 sources:['q:28:7','q:4:164','q:26:63'],
 quiz:[
  {q:"In welk land werd de profeet Moesa (Mozes) geboren?",c:["In Egypte","In Arabië","In Irak","In Jemen"],b:0,e:"Hij werd geboren in Egypte, onder het bewind van Farao.",s:['q:28:7']},
  {q:"Wat deed de moeder van Moesa om hem tegen Farao te beschermen?",c:["Ze legde hem op de rivier","Ze verstopte hem in een grot","Ze vertrok naar de woestijn","Ze vertrouwde hem toe aan een herder"],b:0,e:"Allah gaf haar in om hem zonder vrees in de rivier te leggen.",s:['q:28:7']},
  {q:"Wie nam Moesa als baby op uit de rivier?",c:["De familie van Farao","Vissers","Ibrahim","Een koning van Jemen"],b:0,e:"De mensen van Farao namen hem op.",s:['q:28:8']},
  {q:"Welke profeet wordt “Kalim Allah” genoemd, degene tot wie Allah rechtstreeks sprak?",c:["Moesa","Ibrahim","ʿIsa","Noeh"],b:0,e:"“En Allah sprak werkelijk tot Moesa.”",s:['q:4:164']},
  {q:"Wat werd de staf van Moesa toen hij hem op de grond wierp?",c:["Een slang","Een boom","Een duif","Een zwaard"],b:0,e:"“Hij wierp hem neer, en zie: het was een kruipende slang.”",s:['q:20:20']},
  {q:"Wat gebeurde er toen Moesa met zijn staf op de zee sloeg?",c:["Ze spleet in tweeën","Ze veranderde in zand","Ze droogde in één keer op","Niets"],b:0,e:"Elk deel was als een enorme berg.",s:['q:26:63']},
  {q:"Wat gebeurde er met Farao en zijn leger, die Moesa achtervolgden?",c:["Ze verdronken in de zee","Ze bekeerden zich","Ze keerden terug naar Egypte","Ze staken ook over"],b:0,e:"Allah redde Moesa en wie bij hem waren, en liet de anderen verdrinken.",s:['q:26:66']},
  {q:"Hoe heette de broer van Moesa, die hem hielp bij zijn zending?",c:["Haroen (Aäron)","Yoesoef","Ishaq","Yahya"],b:0,e:"Moesa vroeg Allah om zijn broer Haroen als helper.",s:['q:20:30']},
  {q:"Naar welke koning zond Allah Moesa?",c:["Farao","Nimrod","De koning van Saba","Goliath"],b:0,e:"“Ga naar Farao, want hij heeft alle grenzen overschreden.”",s:['q:20:24']},
  {q:"Welke profeet wordt het vaakst bij naam genoemd in de Koran?",c:["Moesa","Mohammed ﷺ","Ibrahim","Noeh"],b:0,e:"Moesa wordt meer dan 130 keer in de Koran genoemd.",s:['f:musa']}
 ]},
'pr-isa':{titre:"ʿIsa en Maryam",
 texte:["Maryam (Maria), de moeder van ʿIsa, is de enige vrouw die in de Koran bij naam wordt genoemd. Allah heeft haar uitverkoren boven de vrouwen van de werelden, en een soera draagt haar naam.",
  "ʿIsa (Jezus) werd zonder vader geboren, door de wil van Allah, zoals Adam werd geschapen zonder vader en moeder. Als baby sprak hij al vanuit de wieg.",
  "Voor moslims is ʿIsa een groot profeet en boodschapper van Allah, de Messias, aan wie de Indjiel (het Evangelie) werd geopenbaard."],
 retenir:"Maryam, uitverkoren onder de vrouwen. ʿIsa, zonder vader geboren, profeet en Messias.",
 sources:['q:3:42','q:3:59','q:19:30'],
 quiz:[
  {q:"Wie is de enige vrouw die in de Koran bij naam wordt genoemd?",c:["Maryam","Khadidja","Asiya","Hawwa"],b:0,e:"Maryam is de enige vrouw die bij naam wordt genoemd; soera 19 draagt haar naam.",s:['f:maryam']},
  {q:"Wat zegt de Koran over Maryam?",c:["Allah heeft haar uitverkoren boven de vrouwen van de werelden","Ze was koningin van Egypte","Ze was een profetes in Medina","De Koran spreekt niet over haar"],b:0,e:"De engelen kondigden haar aan dat Allah haar had uitverkoren en gezuiverd.",s:['q:3:42']},
  {q:"Hoe werd de profeet ʿIsa (Jezus) geboren?",c:["Zonder vader, door de wil van Allah","Zoals iedereen","In het paleis van Farao","In Mekka"],b:0,e:"Allah zei “Wees”, en hij was.",s:['q:3:59']},
  {q:"Met de schepping van wie vergelijkt de Koran die van ʿIsa?",c:["Met die van Adam","Met die van de engelen","Met die van Noeh","Met die van Iblies"],b:0,e:"Adam werd geschapen zonder vader en moeder; ʿIsa zonder vader.",s:['q:3:59']},
  {q:"Welk wonder verrichtte ʿIsa toen hij een baby was?",c:["Hij sprak vanuit de wieg","Hij liep over het water","Hij liet het water van Zamzam opborrelen","Hij stak de zee over"],b:0,e:"Hij verdedigde zijn moeder door vanuit de wieg te spreken.",s:['q:19:30']},
  {q:"Wat waren volgens de Koran de eerste woorden van ʿIsa als baby?",c:["“Ik ben de dienaar van Allah”","“Ik ben koning”","“Ik ben een engel”","“Ik ben de zoon van Zakariyya”"],b:0,e:"“Ik ben waarlijk de dienaar van Allah. Hij heeft mij het Boek gegeven en mij tot profeet gemaakt.”",s:['q:19:30']},
  {q:"Welke titel geeft de Koran aan ʿIsa?",c:["Al-Masih, de Messias","De Khalil","Het zegel der profeten","Kalim Allah"],b:0,e:"De engelen kondigen aan Maryam aan: “zijn naam is Al-Masih, ʿIsa, zoon van Maryam”.",s:['q:3:45']},
  {q:"Welk boek heeft Allah aan de profeet ʿIsa geopenbaard?",c:["De Indjiel (het Evangelie)","De Tawrat (de Thora)","De Zaboer (de Psalmen)","De Koran"],b:0,e:"“Wij gaven hem het Evangelie, waarin leiding en licht is.”",s:['q:5:46']},
  {q:"Wie is ʿIsa voor moslims?",c:["Een profeet en boodschapper van Allah","Een godheid","Een engel","Een koning van Jeruzalem"],b:0,e:"Hij stelt zichzelf voor als dienaar van Allah en profeet.",s:['q:19:30']},
  {q:"Wie werd naar Maryam gezonden om haar de geboorte van ʿIsa aan te kondigen?",c:["De Geest van Allah, de engel Djibriel","Zakariyya","Yahya","De engel Mikaʾiel"],b:0,e:"De geleerden leggen uit dat “Onze Geest” de engel Djibriel aanduidt.",s:['q:19:19']}
 ]},
'pr-muhammad':{titre:"Mohammed ﷺ, de laatste profeet",
 texte:["Mohammed ﷺ werd rond 570 in Mekka geboren, in het “jaar van de Olifant”, in de stam Qoeraisj. Zijn vader overleed vóór zijn geboorte, zijn moeder Amina verloor hij op 6-jarige leeftijd. Hij werd opgevoed door zijn grootvader en daarna door zijn oom Abu Talib.",
  "Hij stond bekend om zijn eerlijkheid en werd al-Amin genoemd, “de betrouwbare”. Hij ontving de eerste openbaring op 40-jarige leeftijd.",
  "Hij overleed in Medina in 632, op 63-jarige leeftijd. Allah heeft hem gezonden als barmhartigheid voor de werelden."],
 retenir:"Geboren in Mekka rond 570, openbaring op 40 jaar, overleden in Medina op 63 jaar.",
 sources:['q:21:107','q:68:4','h:vie'],
 quiz:[
  {q:"In welke stad werd de Profeet Mohammed ﷺ geboren?",c:["Mekka","Medina","Jeruzalem","Taʾif"],b:0,e:"Hij werd rond 570 in Mekka geboren.",s:['f:sira']},
  {q:"Hoe wordt het geboortejaar van de Profeet ﷺ genoemd?",c:["Het jaar van de Olifant","Het jaar van de Hidjra","Het jaar van de droefheid","Het jaar van de overwinning"],b:0,e:"Het jaar waarin een leger met olifanten Mekka aanviel (soera 105).",s:['q:105:1']},
  {q:"Hoe heette de moeder van de Profeet ﷺ?",c:["Amina","Khadidja","Halima","Fatima"],b:0,e:"Amina bint Wahb overleed toen hij 6 jaar was.",s:['f:sira']},
  {q:"Welke oom voedde de Profeet ﷺ op en beschermde hem?",c:["Abu Talib","Abu Lahab","Hamza","Al-ʿAbbas"],b:0,e:"Na de dood van zijn grootvader nam zijn oom Abu Talib de zorg voor hem op zich.",s:['f:sira']},
  {q:"Welke bijnaam gaven de Mekkanen aan de Profeet ﷺ vóór de openbaring?",c:["Al-Amin, de betrouwbare","Al-Faroeq","As-Siddiq","Sayf Allah"],b:0,e:"Iedereen kende hem om zijn eerlijkheid.",s:['f:sira']},
  {q:"Op welke leeftijd overleed de Profeet ﷺ?",c:["63 jaar","40 jaar","70 jaar","53 jaar"],b:0,e:"Ibn ʿAbbas vertelt dat hij op 63-jarige leeftijd overleed.",s:['h:vie']},
  {q:"In welke stad overleed de Profeet ﷺ?",c:["Medina","Mekka","Jeruzalem","Damascus"],b:0,e:"Hij overleed in 632 in Medina en is daar begraven.",s:['f:sira']},
  {q:"Waarom heeft Allah Mohammed ﷺ volgens de Koran gezonden?",c:["Als barmhartigheid voor de werelden","Om koning te zijn","Om de mensen te straffen","Alleen voor de Arabieren"],b:0,e:"“Wij hebben jou slechts gezonden als barmhartigheid voor de werelden.”",s:['q:21:107']},
  {q:"Wat zegt de Koran over het karakter van de Profeet ﷺ?",c:["Hij heeft een voortreffelijk karakter","Hij is streng","Hij is onverschillig","De Koran spreekt er niet over"],b:0,e:"“En voorwaar, jij bezit een voortreffelijk karakter.”",s:['q:68:4']},
  {q:"Tot welke stam behoorde de Profeet ﷺ?",c:["Qoeraisj","Aws","Khazradj","Thaqief"],b:0,e:"Qoeraisj, de grote stam van Mekka.",s:['f:sira']}
 ]},
'pr-livres':{titre:"De geopenbaarde boeken en het geloof",
 texte:["Allah heeft aan sommige profeten boeken geopenbaard: de Tawrat (Thora) aan Moesa, de Zaboer (Psalmen) aan Dawoed, de Indjiel (Evangelie) aan ʿIsa, en de Koran aan Mohammed ﷺ.",
  "De Koran noemt 25 profeten bij naam, maar Allah heeft er veel meer gezonden. De gelovige gelooft in hen allen, zonder onderscheid.",
  "Het geloof (iman) rust op zes zuilen: geloven in Allah, in Zijn engelen, in Zijn boeken, in Zijn boodschappers, in de Laatste Dag en in de voorbeschikking."],
 retenir:"Tawrat, Zaboer, Indjiel, Koran. Zes zuilen van het geloof.",
 sources:['q:5:44','q:2:285','h:jibril'],
 quiz:[
  {q:"Welk boek heeft Allah aan de profeet Moesa (Mozes) geopenbaard?",c:["De Tawrat (Thora)","De Zaboer (Psalmen)","De Indjiel (Evangelie)","De Koran"],b:0,e:"De Tawrat aan Moesa, de Zaboer aan Dawoed, de Indjiel aan ʿIsa, de Koran aan Mohammed ﷺ.",s:['q:5:44']},
  {q:"Hoeveel profeten worden in de Koran bij naam genoemd?",c:["25","12","40","313"],b:0,e:"25 profeten worden bij naam genoemd; 18 van hen samen in soera Al-Anʿam.",s:['f:prophetes25']},
  {q:"Welke profeet noemt de Koran “het zegel der profeten”, dat wil zeggen de laatste?",c:["Mohammed ﷺ","ʿIsa (Jezus)","Moesa (Mozes)","Ibrahim (Abraham)"],b:0,e:"Mohammed ﷺ is de laatste van de profeten.",s:['q:33:40']},
  {q:"Welk boek werd aan de profeet Dawoed (David) geopenbaard?",c:["De Zaboer (Psalmen)","De Tawrat","De Indjiel","De bladen van Ibrahim"],b:0,e:"“En aan Dawoed gaven Wij de Zaboer.”",s:['q:4:163']},
  {q:"Hoort het geloof in de geopenbaarde boeken bij het geloof van de moslim?",c:["Ja, het is een zuil van het geloof","Nee, alleen in de Koran","Nee, het is vrijblijvend","Alleen tijdens Ramadan"],b:0,e:"De gelovigen geloven in Allah, Zijn engelen, Zijn boeken en Zijn boodschappers.",s:['q:2:285']},
  {q:"Hoeveel zuilen telt het geloof (iman)?",c:["6","5","4","10"],b:0,e:"Allah, de engelen, de boeken, de boodschappers, de Laatste Dag en de voorbeschikking.",s:['h:jibril']},
  {q:"Welke van deze is GEEN zuil van het geloof (iman)?",c:["Het vasten van Ramadan","Het geloof in de engelen","Het geloof in de Laatste Dag","Het geloof in de boeken"],b:0,e:"Het vasten is een zuil van de islam (de praktijk), niet van het geloof (de overtuiging).",s:['h:jibril']},
  {q:"Welk boek heeft Allah beloofd te bewaren?",c:["De Koran","De Tawrat","De Zaboer","Alle boeken van de koningen"],b:0,e:"“En Wij zijn er de Bewaarders van.”",s:['q:15:9']},
  {q:"Vertelt de Koran het verhaal van alle boodschappers die Allah heeft gezonden?",c:["Nee, alleen van sommigen","Ja, van allemaal","Hij vertelt over geen enkele","Alleen over de Arabieren"],b:0,e:"“Er zijn boodschappers over wie Wij jou hebben verteld, en boodschappers over wie Wij jou niet hebben verteld.”",s:['q:4:164']},
  {q:"Maken de gelovigen volgens de Koran in hun geloof onderscheid tussen de boodschappers?",c:["Nee, ze geloven in hen allen","Ja, ze geloven er maar in één","Ja, ze verwerpen de vroegere","Ze geloven in geen van hen"],b:0,e:"“Wij maken geen onderscheid tussen Zijn boodschappers.”",s:['q:2:285']}
 ]},

/* ===================== GESCHIEDENIS & METGEZELLEN ===================== */
'h-khadija':{titre:"Khadidja en het begin van de islam",
 texte:["Khadidja was een gerespecteerde koopvrouw in Mekka. Ze trouwde met de Profeet ﷺ, die toen 25 jaar oud was.",
  "Na de eerste openbaring was zij het die hem troostte en als eerste in hem geloofde. Ze nam hem mee naar haar neef Waraqa ibn Nawfal.",
  "Tot de eerste moslims behoren Abu Bakr, ʿAli, Zayd ibn Haritha en Bilal. Dertien jaar lang werden de moslims in Mekka vervolgd; Soemayya was de eerste martelares."],
 retenir:"Khadidja, de eerste die geloofde. 13 jaar prediking in Mekka.",
 sources:['h:hira','f:debuts'],
 quiz:[
  {q:"Wie was de eerste vrouw van de Profeet ﷺ?",c:["Khadidja","ʿAisja","Hafsa","Zaynab"],b:0,e:"Khadidja was de eerste persoon die in zijn boodschap geloofde.",s:['h:hira']},
  {q:"Wie troostte de Profeet ﷺ direct na de eerste openbaring in de grot Hira?",c:["Khadidja","Abu Bakr","ʿAli","Bilal"],b:0,e:"Hij ging terug naar Khadidja, die hem geruststelde.",s:['h:hira']},
  {q:"Welk beroep oefende Khadidja uit in Mekka?",c:["De handel","De geneeskunde","De dichtkunst","Het fokken van kamelen"],b:0,e:"Ze was een rijke en gerespecteerde koopvrouw.",s:['f:debuts']},
  {q:"Hoe oud was de Profeet ﷺ toen hij met Khadidja trouwde?",c:["25 jaar","40 jaar","18 jaar","30 jaar"],b:0,e:"Hij was 25 jaar.",s:['f:debuts']},
  {q:"Naar wie nam Khadidja de Profeet ﷺ mee na de eerste openbaring?",c:["Haar neef Waraqa ibn Nawfal","Abu Talib","Abu Bakr","De koning van Abessinië"],b:0,e:"Waraqa kende de oude Schriften.",s:['h:hira']},
  {q:"Welke jonge jongen was een van de eersten die de islam aannamen?",c:["ʿAli ibn Abi Talib","ʿUmar","Khalid","Muʿawiya"],b:0,e:"ʿAli, de neef van de Profeet ﷺ, was toen nog een kind.",s:['f:debuts']},
  {q:"Hoeveel jaar ongeveer predikte de Profeet ﷺ in Mekka vóór de Hidjra?",c:["13 jaar","3 jaar","23 jaar","40 jaar"],b:0,e:"Ibn ʿAbbas vertelt dat hij na de openbaring 13 jaar in Mekka bleef.",s:['h:vie']},
  {q:"Welke vriend van de Profeet ﷺ was de eerste volwassen man die de islam aannam?",c:["Abu Bakr","ʿUmar","ʿUthman","Hamza"],b:0,e:"Abu Bakr geloofde zonder aarzelen in hem.",s:['f:debuts']},
  {q:"Welke voormalige slaaf, vervolgd om zijn geloof, werd de eerste muezzin van de islam?",c:["Bilal ibn Rabah","Zayd ibn Haritha","Salman","Anas"],b:0,e:"Zijn stem droeg ver: de Profeet ﷺ vertrouwde hem de adhan toe.",s:['h:adhan']},
  {q:"Hoe heette de eerste martelares van de islam?",c:["Soemayya","Khadidja","Fatima","Asmaʾ"],b:0,e:"Soemayya, de moeder van ʿAmmar, werd in Mekka om haar geloof gedood.",s:['f:debuts']}
 ]},
'h-hegire':{titre:"De Hidjra",
 texte:["In 622 verliet de Profeet ﷺ, vanwege de vervolgingen, Mekka voor Medina, dat toen Yathrib heette: dat is de Hidjra. Ze markeert het jaar 1 van de islamitische kalender.",
  "Tijdens de reis verborg hij zich in de grot Thawr met zijn vriend Abu Bakr.",
  "In Medina werd hij ontvangen door de Ansar (de “Helpers”), die hun bezittingen deelden met de Muhadjiroen (de “Emigranten”). Hij bouwde er zijn moskee."],
 retenir:"622: de Hidjra, jaar 1. Muhadjiroen en Ansar.",
 sources:['q:9:40','f:hegire'],
 quiz:[
  {q:"Wat is de Hidjra?",c:["De migratie van de Profeet ﷺ van Mekka naar Medina","De eerste bedevaart","Een veldslag","De geboorte van de Profeet ﷺ"],b:0,e:"Ze markeert het jaar 1 van de islamitische kalender.",s:['f:hegire']},
  {q:"Welke metgezel vergezelde de Profeet ﷺ in de grot tijdens de Hidjra?",c:["Abu Bakr as-Siddiq","ʿUmar ibn al-Khattab","ʿAli ibn Abi Talib","Bilal"],b:0,e:"Abu Bakr was “de tweede van de twee” in de grot.",s:['q:9:40']},
  {q:"In welk jaar vond de Hidjra plaats?",c:["622","570","632","610"],b:0,e:"De Hidjra vond plaats in 622 van de christelijke jaartelling.",s:['f:hegire']},
  {q:"In welke grot verborg de Profeet ﷺ zich tijdens de Hidjra?",c:["De grot Thawr","De grot Hira","De grot van Uhud","De grot van Badr"],b:0,e:"Thawr ligt ten zuiden van Mekka; Hira, de plaats van de eerste openbaring, ten noorden.",s:['f:hegire']},
  {q:"Wat was de vroegere naam van Medina?",c:["Yathrib","Bakka","Taʾif","Qubaʾ"],b:0,e:"De Koran noemt deze naam: “O mensen van Yathrib”.",s:['q:33:13']},
  {q:"Hoe heten de inwoners van Medina die de moslims opvingen?",c:["De Ansar","De Muhadjiroen","De Qoeraisj","De Banoe Israʾiel"],b:0,e:"Ansar betekent “de Helpers”.",s:['q:9:100']},
  {q:"Hoe heten de moslims die van Mekka naar Medina emigreerden?",c:["De Muhadjiroen","De Ansar","De Khawaridj","De bedoeïenen"],b:0,e:"Muhadjiroen betekent “de Emigranten”.",s:['q:9:100']},
  {q:"Wat zei de Profeet ﷺ volgens de Koran tegen Abu Bakr in de grot?",c:["“Wees niet bedroefd, Allah is met ons”","“Laten we snel vluchten”","“Laten we teruggaan naar Mekka”","“Laten we tegen hen vechten”"],b:0,e:"Dit is vers 40 van soera At-Tawba.",s:['q:9:40']},
  {q:"Onder welke kalief werd de Hidjri-kalender ingevoerd?",c:["ʿUmar","Abu Bakr","ʿUthman","ʿAli"],b:0,e:"ʿUmar maakte de Hidjra tot het beginpunt van de kalender.",s:['f:hegire']},
  {q:"Wat bouwde de Profeet ﷺ bij zijn aankomst in Medina?",c:["Zijn moskee","Een paleis","Een vesting","Een markt"],b:0,e:"De Moskee van de Profeet (al-Masdjid an-Nabawi).",s:['f:hegire']}
 ]},
'h-badr':{titre:"De slag bij Badr",
 texte:["Op 17 Ramadan van het jaar 2 van de Hidjra (624) stonden de moslims tegenover het leger van Qoeraisj, bij de bronnen van Badr.",
  "Ze waren met ongeveer 313, tegenover bijna 1000 strijders. Allah steunde hen met engelen, en ze behaalden de overwinning.",
  "De Koran noemt deze dag “de dag van het Onderscheid” (yawm al-furqan), de dag waarop de waarheid van de dwaling werd onderscheiden."],
 retenir:"17 Ramadan jaar 2: Badr, 313 tegen 1000, de dag van het Onderscheid.",
 sources:['q:3:123','q:8:9','q:8:41'],
 quiz:[
  {q:"In welke maand vond de slag bij Badr plaats?",c:["Ramadan","Muharram","Dhul-Hiddja","Radjab"],b:0,e:"Op 17 Ramadan van het jaar 2 van de Hidjra.",s:['f:badr']},
  {q:"In welk jaar van de Hidjra vond de slag bij Badr plaats?",c:["Het jaar 2","Het jaar 8","Het jaar 10","Het jaar 1"],b:0,e:"In 624 van de christelijke jaartelling.",s:['f:badr']},
  {q:"Met hoeveel moslims ongeveer vochten ze bij Badr?",c:["Ongeveer 313","Ongeveer 3000","Ongeveer 10.000","Ongeveer 50"],b:0,e:"Ze waren met ongeveer 313.",s:['f:badr']},
  {q:"Hoeveel strijders telde het leger van Qoeraisj bij Badr ongeveer?",c:["Bijna 1000","Bijna 100","Bijna 10.000","Bijna 300"],b:0,e:"De Mekkanen waren drie keer zo talrijk.",s:['f:badr']},
  {q:"Hoe steunde Allah volgens de Koran de moslims bij Badr?",c:["Met engelen","Met een zandstorm","Met versterkingen uit Perzië","Alleen met regen"],b:0,e:"Allah verhoorde hun smeekbede door engelen te zenden.",s:['q:8:9']},
  {q:"Hoeveel engelen beloofde Allah volgens soera Al-Anfal als versterking bij Badr te zenden?",c:["Duizend","Honderd","Tien","Driehonderd"],b:0,e:"“Ik zal jullie helpen met duizend engelen, de een na de ander.”",s:['q:8:9']},
  {q:"Hoe noemt de Koran de dag van Badr?",c:["De dag van het Onderscheid (yawm al-furqan)","De Dag der Opstanding","De dag van het feest","De dag van de Hidjra"],b:0,e:"De dag waarop de waarheid van de dwaling werd onderscheiden.",s:['q:8:41']},
  {q:"Tegen welke stam vochten de moslims bij Badr?",c:["Qoeraisj","De Romeinen","De Perzen","De Ansar"],b:0,e:"Het leger van Qoeraisj kwam uit Mekka.",s:['f:badr']},
  {q:"Op welke dag van Ramadan vond de slag bij Badr plaats?",c:["De 17e","De 27e","De 1e","De 10e"],b:0,e:"Op 17 Ramadan van het jaar 2.",s:['f:badr']},
  {q:"In welke situatie verkeerden de moslims volgens de Koran bij Badr?",c:["Ze waren zwak en vernederd","Ze waren zeer talrijk","Ze waren rijk","Ze waren te paard"],b:0,e:"“Allah heeft jullie bij Badr de overwinning gegeven, terwijl jullie zwak waren.”",s:['q:3:123']}
 ]},
'h-fath':{titre:"De verovering van Mekka",
 texte:["In het jaar 8 van de Hidjra (630), tijdens de maand Ramadan, trok de Profeet ﷺ Mekka binnen met ongeveer 10.000 moslims, vrijwel zonder strijd.",
  "Hij vergaf zijn vroegere vijanden en zuiverde de Kaaba van haar 360 afgodsbeelden, terwijl hij reciteerde: “De waarheid is gekomen en de valsheid is verdwenen.”",
  "Soera An-Nasr kondigt deze hulp van Allah aan en het massaal toetreden van de mensen tot de islam."],
 retenir:"Ramadan jaar 8: Mekka geopend, de afgodsbeelden gebroken, vergeving geschonken.",
 sources:['q:17:81','h:idoles','q:110:1'],
 quiz:[
  {q:"In welk jaar van de Hidjra werd Mekka veroverd?",c:["Het jaar 8","Het jaar 2","Het jaar 1","Het jaar 11"],b:0,e:"In 630 van de christelijke jaartelling.",s:['f:fath']},
  {q:"In welke maand vond de verovering van Mekka plaats?",c:["Ramadan","Sjawwal","Dhul-Hiddja","Muharram"],b:0,e:"De verovering van Mekka vond plaats in Ramadan.",s:['f:fath']},
  {q:"Hoeveel moslims ongeveer vergezelden de Profeet ﷺ bij de verovering van Mekka?",c:["Ongeveer 10.000","Ongeveer 313","Ongeveer 1000","Ongeveer 100"],b:0,e:"Een leger van ongeveer 10.000 man.",s:['f:fath']},
  {q:"Hoeveel afgodsbeelden stonden er rond de Kaaba op de dag van de verovering van Mekka?",c:["360","12","99","1000"],b:0,e:"ʿAbdallah ibn Masʿoed vertelt dat het er 360 waren.",s:['h:idoles']},
  {q:"Welk vers reciteerde de Profeet ﷺ terwijl hij de afgodsbeelden van de Kaaba neerhaalde?",c:["“De waarheid is gekomen en de valsheid is verdwenen”","“In de naam van Allah”","“Zeg: Hij is Allah, de Ene”","“Lees!”"],b:0,e:"Het is vers 81 van soera Al-Israʾ.",s:['q:17:81','h:idoles']},
  {q:"Hoe behandelde de Profeet ﷺ na de verovering zijn vroegere Mekkaanse vijanden?",c:["Hij vergaf hun","Hij verjoeg hen","Hij zette hen gevangen","Hij verbande hen naar Abessinië"],b:0,e:"Hij schonk de Mekkanen een algemene vergeving.",s:['f:fath']},
  {q:"Welke soera kondigt “de hulp van Allah en de overwinning” aan?",c:["An-Nasr (110)","Al-Fath (48)","Al-Fiel (105)","Al-Kawthar (108)"],b:0,e:"“Wanneer de hulp van Allah en de overwinning komen.”",s:['q:110:1']},
  {q:"Hoe traden de mensen volgens soera An-Nasr toe tot de islam?",c:["In grote groepen","Een voor een, in het geheim","Onder dwang","Niemand trad toe"],b:0,e:"“En je de mensen in grote groepen de godsdienst van Allah ziet binnengaan.”",s:['q:110:2']},
  {q:"Gebeurde de verovering van Mekka door een grote veldslag?",c:["Nee, vrijwel zonder strijd","Ja, de grootste uit de geschiedenis","Ja, een jaar lang","Ja, aan de voet van de berg Uhud"],b:0,e:"De stad werd vreedzaam geopend, vrijwel zonder gevechten.",s:['f:fath']},
  {q:"Waartoe roept soera An-Nasr op na de overwinning?",c:["Allah verheerlijken en Hem om vergeving vragen","Meteen de hadj verrichten","Drie dagen vasten","De Kaaba herbouwen"],b:0,e:"“Verheerlijk dan de lof van je Heer en vraag Hem om vergeving.”",s:['q:110:3']}
 ]},
'h-califes':{titre:"De eerste vier kaliefen",
 texte:["Na de dood van de Profeet ﷺ in 632 volgden vier kaliefen elkaar op: Abu Bakr, ʿUmar, ʿUthman en ʿAli. Zij worden de “rechtgeleide kaliefen” genoemd.",
  "Abu Bakr liet de Koran door Zayd ibn Thabit in één verzameling bijeenbrengen. Onder ʿUmar breidde de islam zich uit en werd de Hidjri-kalender ingevoerd.",
  "ʿUthman liet de Koran in meerdere exemplaren kopiëren, die naar de provincies werden gestuurd. ʿAli, neef en schoonzoon van de Profeet ﷺ, was de vierde kalief."],
 retenir:"Abu Bakr, ʿUmar, ʿUthman, ʿAli: de vier rechtgeleide kaliefen.",
 sources:['h:compilation','h:copies','f:califes'],
 quiz:[
  {q:"Wie was de eerste kalief na de dood van de Profeet ﷺ?",c:["Abu Bakr","ʿUmar","ʿAli","ʿUthman"],b:0,e:"Abu Bakr, daarna ʿUmar, ʿUthman en ʿAli.",s:['f:califes']},
  {q:"Hoeveel “rechtgeleide kaliefen” volgden de Profeet ﷺ op?",c:["4","3","5","12"],b:0,e:"Zij worden al-khulafaʾ ar-rashidoen genoemd.",s:['f:califes']},
  {q:"Wat is de volgorde van de eerste vier kaliefen?",c:["Abu Bakr, ʿUmar, ʿUthman, ʿAli","ʿAli, ʿUmar, Abu Bakr, ʿUthman","ʿUmar, Abu Bakr, ʿAli, ʿUthman","ʿUthman, ʿAli, ʿUmar, Abu Bakr"],b:0,e:"Van 632 tot 661.",s:['f:califes']},
  {q:"Onder welke kalief werd de Koran voor het eerst in één verzameling bijeengebracht?",c:["Abu Bakr","ʿUmar","ʿUthman","ʿAli"],b:0,e:"Na de slag bij Yamama, waarbij veel Koranreciteerders werden gedood.",s:['h:compilation']},
  {q:"Welke metgezel kreeg onder Abu Bakr de opdracht de Koran bijeen te brengen?",c:["Zayd ibn Thabit","Bilal","Khalid ibn al-Walid","Salman"],b:0,e:"Zayd ibn Thabit was schrijver van de openbaring geweest.",s:['h:compilation']},
  {q:"Welke kalief liet de Koran in meerdere exemplaren kopiëren en naar de provincies sturen?",c:["ʿUthman","Abu Bakr","ʿUmar","ʿAli"],b:0,e:"Om de recitatie in de hele moslimwereld eenvormig te maken.",s:['h:copies']},
  {q:"Wat was de familieband tussen ʿAli en de Profeet ﷺ?",c:["Zijn neef en schoonzoon","Zijn broer","Zijn oom","Zijn grootvader"],b:0,e:"ʿAli was de echtgenoot van Fatima, de dochter van de Profeet ﷺ.",s:['f:califes']},
  {q:"Welke kalief had de bijnaam “al-Faroeq”, degene die waarheid van valsheid onderscheidt?",c:["ʿUmar","Abu Bakr","ʿUthman","ʿAli"],b:0,e:"ʿUmar ibn al-Khattab.",s:['f:califes']},
  {q:"Welke kalief had de bijnaam “as-Siddiq”, de waarachtige?",c:["Abu Bakr","ʿUmar","ʿUthman","ʿAli"],b:0,e:"Abu Bakr geloofde onmiddellijk alles wat de Profeet ﷺ vertelde.",s:['f:califes']},
  {q:"Welke kalief trouwde na elkaar met twee dochters van de Profeet ﷺ?",c:["ʿUthman","ʿUmar","Abu Bakr","ʿAli"],b:0,e:"Vandaar zijn bijnaam “Dhoe n-Noerayn”, de man met de twee lichten.",s:['f:califes']}
 ]}
},

/* Referentiepunten (historische of praktische bronnen, zonder Arabische tekst) */
faits:{
 mois:{titre:"Referentiepunt",texte:"De 12 Hidjri-maanden: Muharram, Safar, Rabiʿ al-awwal, Rabiʿ ath-thani, Djumada al-oela, Djumada al-akhira, Radjab, Sjaʿban, Ramadan, Sjawwal, Dhul-Qaʿda, Dhul-Hiddja."},
 jeune2:{titre:"Historisch referentiepunt",texte:"Het vasten van Ramadan werd in Medina voorgeschreven, in het jaar 2 van de Hidjra (624)."},
 conditions:{titre:"Referentiepunt",texte:"De geleerden noemen als voorwaarden voor de verplichting om te vasten: moslim zijn, volwassen (geslachtsrijp) zijn, bij zijn verstand zijn en in staat zijn om te vasten."},
 aid:{titre:"Referentiepunt",texte:"De islam kent twee feesten: het Suikerfeest (Eid al-Fitr), op 1 Sjawwal, aan het einde van Ramadan, en het Offerfeest (Eid al-Adha), op 10 Dhul-Hiddja, tijdens de hadj."},
 shahada:{titre:"Referentiepunt",texte:"Tekst van de sjahada: “Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh” — “Ik getuig dat er geen god is dan Allah, en ik getuig dat Mohammed de Boodschapper van Allah is”."},
 rakat:{titre:"Overgeleverde praktijk",texte:"Het aantal eenheden van elk gebed komt uit de praktijk van de Profeet ﷺ, overgeleverd door alle moslims: Fadjr 2, Dhohr 4, ʿAsr 4, Maghrib 3, ʿIshaa' 4, samen 17 rakʿat per dag."},
 zakat:{titre:"Referentiepunt",texte:"De zakat over geld bedraagt 2,5% (een veertigste) van het spaargeld dat de nisab bereikt en een maanjaar lang in bezit blijft (de hawl). De sadaqa is een vrijwillige aalmoes. Voor bijzondere gevallen moet je het een geleerde vragen."},
 hajj:{titre:"Referentiepunt",texte:"De hadj vindt plaats van 8 tot 13 Dhul-Hiddja. De pelgrim treedt in ihram (mannen dragen twee ongenaaide witte doeken), verricht de tawaf (zeven rondes om de Kaaba) en de saʿy (zeven keer de weg tussen Safa en Marwa). De 9e is de dag van ʿArafa, de 10e het Offerfeest."},
 coran:{titre:"Referentiepunt",texte:"De Koran telt 114 soera's en 6236 verzen volgens de meest gangbare telling. Hij is verdeeld in 30 delen (djuzʾ). Een vers heet aya. De soera's die vóór de Hidjra werden geopenbaard, heten Mekkaans; die erna Medinensisch. De langste is Al-Baqara (286 verzen)."},
 tawba:{titre:"Referentiepunt",texte:"Soera At-Tawba (9) is de enige van de 114 soera's die niet begint met “Bismi Llâhi r-Raḥmâni r-Raḥîm”."},
 ikhlas:{titre:"Referentiepunt",texte:"Al-Ikhlas betekent “het zuivere monotheïsme, de oprechtheid”: de soera zuivert het geloof van elke vorm van afgoderij."},
 hawwa:{titre:"Referentiepunt",texte:"De Koran noemt de vrouw van Adam zonder haar naam te geven. Haar naam, Hawwa (Eva), komt uit de soenna en van de geleerden."},
 musa:{titre:"Referentiepunt",texte:"Moesa is de profeet die het vaakst bij naam wordt genoemd in de Koran: meer dan 130 keer."},
 maryam:{titre:"Referentiepunt",texte:"Maryam is de enige vrouw die in de Koran bij naam wordt genoemd. Soera 19 draagt haar naam."},
 sira:{titre:"Historisch referentiepunt",texte:"De Profeet ﷺ werd rond 570 in Mekka geboren, in de stam Qoeraisj. Zijn vader was al overleden; zijn moeder Amina verloor hij op 6-jarige leeftijd. Hij werd opgevoed door zijn grootvader ʿAbd al-Muttalib en daarna door zijn oom Abu Talib. Men noemde hem al-Amin. Hij overleed in 632 in Medina."},
 prophetes25:{titre:"Referentiepunt",texte:"In de Koran worden 25 profeten bij naam genoemd. 18 van hen worden samen genoemd in soera Al-Anʿam (6), verzen 83 tot 86."},
 debuts:{titre:"Historisch referentiepunt",texte:"Khadidja, een rijke koopvrouw, trouwde met de Profeet ﷺ toen hij 25 jaar was. Tot de allereerste moslims behoren: Khadidja, Abu Bakr, ʿAli (nog een kind) en Zayd ibn Haritha. Bilal, een vervolgde en later vrijgelaten slaaf, werd de eerste muezzin. Soemayya, de moeder van ʿAmmar, was de eerste martelares."},
 hegire:{titre:"Historisch referentiepunt",texte:"De Hidjra vond plaats in 622. De Profeet ﷺ en Abu Bakr verborgen zich in de grot Thawr. Medina heette Yathrib. De Profeet ﷺ bouwde er zijn moskee. De Hidjri-kalender werd ingevoerd onder het kalifaat van ʿUmar."},
 badr:{titre:"Historisch referentiepunt",texte:"De slag bij Badr vond plaats op 17 Ramadan van het jaar 2 (624). Ongeveer 313 moslims stonden tegenover bijna 1000 strijders van Qoeraisj."},
 fath:{titre:"Historisch referentiepunt",texte:"Mekka werd in Ramadan van het jaar 8 (630) geopend, vrijwel zonder strijd, door ongeveer 10.000 moslims. De Profeet ﷺ schonk de Mekkanen een algemene vergeving."},
 califes:{titre:"Historisch referentiepunt",texte:"De vier rechtgeleide kaliefen: Abu Bakr as-Siddiq (632-634), ʿUmar al-Faroeq (634-644), ʿUthman Dhoe n-Noerayn (644-656), die met twee dochters van de Profeet ﷺ trouwde, eerst Ruqayya en daarna Umm Kulthum, en ʿAli (656-661), neef van de Profeet ﷺ en echtgenoot van zijn dochter Fatima."}
},

/* Samenvattingen voor lange hadiths (de volledige tekst blijft beschikbaar) */
resumes:{
 cinq:"Tijdens de Nachtreis (al-Israa' wal-Miʿradj) werden eerst vijftig gebeden voorgeschreven, die daarna werden verlicht tot vijf gebeden per dag.",
 enfants:"Ar-Rubayyiʿ bint Muʿawwidh vertelt dat de metgezellen hun jonge kinderen lieten vasten op de dag van ʿAsjoera, en hun speelgoed van wol gaven om geduldig te wachten tot het verbreken van het vasten.",
 hira:"ʿAisja vertelt dat de Profeet ﷺ zich terugtrok in de grot Hira. De engel kwam en zei tegen hem: “Lees!”. Hij ging terug naar Khadidja, die hem troostte en hem daarna meenam naar haar neef Waraqa ibn Nawfal.",
 regles:"ʿAisja legt uit dat hun werd opgedragen het tijdens de menstruatie gemiste vasten in te halen, maar niet het gebed.",
 tarawih:"De Profeet ﷺ bad tijdens Ramadan 's nachts in de moskee; mensen baden achter hem, steeds talrijker. Toen kwam hij niet meer naar buiten, uit vrees dat dit gebed voor hen verplicht zou worden.",
 adhan:"De metgezel ʿAbdallah ibn Zayd zag de woorden van de adhan in een droom. De Profeet ﷺ bevestigde deze droom en vroeg Bilal de oproep te doen, omdat zijn stem verder droeg.",
 ikhlas:"Een man reciteerde steeds soera Al-Ikhlas en vond dat weinig. De Profeet ﷺ zei: “Ze staat gelijk aan een derde van de Koran.”",
 kursi:"De Profeet ﷺ vroeg Ubayy ibn Kaʿb wat het grootste vers uit het Boek van Allah is. Hij antwoordde: Ayat al-Koersi. De Profeet ﷺ prees hem om zijn kennis.",
 hajj_une:"De Profeet ﷺ kondigde aan dat de hadj was voorgeschreven. Een man vroeg: “Elk jaar?” Hij antwoordde dat als hij ja zou zeggen, het elk jaar verplicht zou worden: hij is één keer verplicht.",
 arafa:"Mensen vroegen de Profeet ﷺ op ʿArafa naar de bedevaart. Hij antwoordde: “De hadj is ʿArafa.”",
 jibril:"De engel Djibriel ondervroeg de Profeet ﷺ in menselijke gedaante over de islam, het geloof en de uitmuntendheid. Het geloof (iman): geloven in Allah, in Zijn engelen, in Zijn boeken, in Zijn boodschappers, in de Laatste Dag en in de voorbeschikking, het goede en het slechte ervan.",
 vie:"Ibn ʿAbbas vertelt dat de Profeet ﷺ de openbaring ontving op 40-jarige leeftijd, 13 jaar in Mekka bleef, naar Medina emigreerde waar hij 10 jaar leefde, en op 63-jarige leeftijd overleed.",
 idoles:"Op de dag van de verovering stonden er 360 afgodsbeelden rond de Kaaba. De Profeet ﷺ sloeg ze met een stok terwijl hij reciteerde: “De waarheid is gekomen en de valsheid is verdwenen.”",
 compilation:"Na de slag bij Yamama, waarbij veel Koranreciteerders werden gedood, gaf Abu Bakr Zayd ibn Thabit de opdracht de Koran in één verzameling bijeen te brengen.",
 copies:"ʿUthman, bezorgd over verschillen in recitatie tussen de provincies, liet de verzameling van de Koran in meerdere exemplaren kopiëren en naar elke regio sturen.",
 fitr_but:"Ibn ʿAbbas vertelt dat de Profeet ﷺ de zakat al-fitr heeft voorgeschreven om de vastende te zuiveren van ijdele en ongepaste woorden, en om de armen te eten te geven.",
 afw:"ʿAisja vroeg wat ze moest zeggen als ze wist welke nacht de Nacht van de Beschikking was. Hij antwoordde: “Zeg: Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî” — O Allah, U bent Degene Die vergeeft, U houdt van vergeving, vergeef mij dus."
}
};
